    function getBuildingSynergyMult(buildingId) {
        if (!GameState.purchasedSynergies || GameState.purchasedSynergies.length === 0) return 1;
        let mult = 1;
        for (const synId of GameState.purchasedSynergies) {
            const syn = SYNERGIES_CONFIG.find(s => s.id === synId);
            if (syn) {
                if (syn.targetBuilding === buildingId || syn.secondTarget === buildingId) {
                    mult *= (typeof syn.getMult === 'function' ? syn.getMult() : 1);
                }
            }
        }
        return mult;
    }

