    // Доход в секунду для наград (без временных бустов): пассив + тап x3 в секунду
    function getRewardIncomePerSec() {
        return getPassiveIncome(true) + getClickPower(true) * 3;
    }
    // Награда задания в монетах: N минут дохода игрока (минимум 30 монет за минуту)
    function getQuestCoinReward(q) {
        const minutes = q.rewardMinutes || 0;
        if (minutes <= 0) return 0;
        let owlBonus = 1;
        const pet = getActivePet();
        if (pet && pet.id === 'owl') owlBonus += 0.25 + getPetLevel('owl') * 0.10;
        return cleanRound(Math.max(minutes * 30, minutes * 60 * getRewardIncomePerSec()) * owlBonus);
    }
    // Жуки есть только на Тёмном пути — на остальных путях «жучиные» задания засчитывают кометы
