    // --- ЭФФЕКТЫ ТАПА (3D наклон, цифры, частицы) ---
    function spawnTapPopup(x, y, value, isCrit, critMult = 5, customText = null) {
        if (GameState.showDmgNumbers === false && !customText) return;
        const popup = document.createElement('div');
        popup.className = 'tap-popup' + (isCrit ? ' crit' : '');
        if (customText) {
            popup.textContent = customText;
        } else {
            popup.textContent = (isCrit ? `🔥 КРИТ x${critMult}! +` : '+') + formatNumber(value) + ' 🪙';
        }

        // Случайный разлет по оси X (-30..+30px)
        const dx = (Math.random() - 0.5) * 60;
        popup.style.setProperty('--dx', `${dx}px`);
        popup.style.left = `${x}px`;
        popup.style.top = `${y}px`;

        dom.tapFxLayer.appendChild(popup);
        setTimeout(() => popup.remove(), 800);
    }

    function spawnTapParticles(x, y) {
        if (GameState.showParticles === false) return;
        const count = feverActive ? 8 : 4;
        const skin = getActiveSkin();
        const color = skin.particleColor || '#ffd700';

        for (let i = 0; i < count; i++) {
            const particle = document.createElement('div');
            particle.className = 'tap-particle';
            const angle = Math.random() * Math.PI * 2;
            const dist = 30 + Math.random() * 50;
            const px = Math.cos(angle) * dist;
            const py = Math.sin(angle) * dist;

            particle.style.background = `radial-gradient(circle, #ffffff 15%, ${color} 80%)`;
            particle.style.boxShadow = `0 0 10px ${color}`;
            particle.style.setProperty('--px', `${px}px`);
            particle.style.setProperty('--py', `${py}px`);
            particle.style.left = `${x}px`;
            particle.style.top = `${y}px`;

            dom.tapFxLayer.appendChild(particle);
            setTimeout(() => particle.remove(), 600);
        }
    }

    // --- КОНФЕТТИ ПРИ ПОИМКЕ ПОДАРКА И КРУПНЫХ НАГРАДАХ ---
    function spawnConfetti(x, y) {
        if (GameState.showParticles === false) return;
        const colors = ['#ffd700', '#ff1744', '#00e5ff', '#e040fb', '#76ff03', '#ff9100', '#ffffff'];
        const count = 38;
        for (let i = 0; i < count; i++) {
            const piece = document.createElement('div');
            piece.className = 'confetti-piece';
            const color = colors[Math.floor(Math.random() * colors.length)];
            const isCircle = Math.random() > 0.6;
            
            piece.style.backgroundColor = color;
            piece.style.borderRadius = isCircle ? '50%' : '2px';
            piece.style.width = isCircle ? '9px' : `${7 + Math.random() * 6}px`;
            piece.style.height = `${8 + Math.random() * 8}px`;

            const angle = Math.random() * Math.PI * 2;
            const dist = 60 + Math.random() * 110;
            const endX = Math.cos(angle) * dist;
            const endY = Math.sin(angle) * dist + 45; // гравитация вниз
            const rot = (Math.random() - 0.5) * 720;
            const duration = (0.9 + Math.random() * 0.5).toFixed(2);

            piece.style.setProperty('--end-x', `${endX}px`);
            piece.style.setProperty('--end-y', `${endY}px`);
            piece.style.setProperty('--rot', `${rot}deg`);
            piece.style.setProperty('--fall-duration', `${duration}s`);

            piece.style.left = `${x}px`;
            piece.style.top = `${y}px`;

            dom.tapFxLayer.appendChild(piece);
            setTimeout(() => piece.remove(), duration * 1000);
        }
    }

    // Защита от автокликеров: засчитываем не больше MAX_TAPS_PER_SECOND тапов в секунду
    const MAX_TAPS_PER_SECOND = 15;
    const recentTapTimes = [];

    // Эксклюзив пропуска «Имперские короны»: из-под пальца вылетает золотая корона (не чаще ~7 раз в секунду)
    let lastCrownAt = 0;
    // какой эффект тапа сейчас включён: короны (Золотой век), салют (Звёздная ярмарка) или выключен
    function tapFxSel() {
        const ex = GameState.ext; if (!ex) return 'off';
        const own = tapFxOwned();
        if (!own.length) return 'off';
        if (ex.tapFxSel === 'off' || (ex.tapFxSel == null && ex.tapCrownsOn === false)) return 'off';
        return own.includes(ex.tapFxSel) ? ex.tapFxSel : own[0];
    }
    function tapFxOwned() { const ex = GameState.ext || {}; const o = []; if (ex.tapCrowns) o.push('crowns'); if (ex.tapFireworks) o.push('fireworks'); return o; }
    const TAP_FX_NAMES = { crowns: 'Короны', fireworks: 'Салют', off: 'выкл' };
    let lastFwAt = 0;
    function spawnTapFireworks(x, y, now) {
        if (now - lastFwAt < (document.body.classList.contains('low-fx') ? 300 : 160)) return;
        lastFwAt = now;
        const b = document.createElement('div');
        b.className = 'tap-fw';
        b.style.left = `${x + (Math.random() - 0.5) * 50}px`; b.style.top = `${y - 20 - Math.random() * 40}px`;
        const cols = ['#f472b6', '#38bdf8', '#fde047', '#a78bfa', '#34d399'];
        const col = cols[Math.floor(Math.random() * cols.length)], col2 = cols[Math.floor(Math.random() * cols.length)];
        const n = document.body.classList.contains('low-fx') ? 8 : 12;
        let h = '';
        for (let i = 0; i < n; i++) h += `<i style="--a:${(360 / n) * i}deg;--c:${i % 2 ? col : col2}"></i>`;
        b.innerHTML = h + '<b></b>';
        document.body.appendChild(b);
        setTimeout(() => b.remove(), 900);
    }
    function spawnTapCrown(x, y, now) {
        const ex = GameState.ext;
        const fx = tapFxSel();
        if (fx === 'fireworks') { spawnTapFireworks(x, y, now); return; }
        if (!ex || fx !== 'crowns') return;
        // платный эффект: в лёгком режиме не выключаем, только реже
        if (now - lastCrownAt < (document.body.classList.contains('low-fx') ? 260 : 140)) return;
        lastCrownAt = now;
        const c = document.createElement('img');
        c.className = 'tap-crown';
        c.src = 'assets/icons/x_crown.svg';
        c.alt = '';
        c.style.left = `${x}px`; c.style.top = `${y}px`;
        c.style.setProperty('--dx', `${Math.round((Math.random() - 0.5) * 90)}px`);
        c.style.setProperty('--rot', `${Math.round((Math.random() - 0.5) * 60)}deg`);
        document.body.appendChild(c);
        setTimeout(() => c.remove(), 1100);
        // вторая, поменьше — веером в другую сторону
        if (!document.body.classList.contains('low-fx')) {
            const c2 = c.cloneNode();
            c2.classList.add('small');
            c2.style.setProperty('--dx', `${-parseInt(c.style.getPropertyValue('--dx')) || 30}px`);
            c2.style.animationDelay = '60ms';
            document.body.appendChild(c2);
            setTimeout(() => c2.remove(), 1200);
        }
    }
    function handleCoinTap(e) {
        // Программные (не настоящие) клики не засчитываются
        if (!IS_DEV && e && e.isTrusted === false) return;
        const tapNow = performance.now();
        while (recentTapTimes.length && tapNow - recentTapTimes[0] > 1000) recentTapTimes.shift();
        if (recentTapTimes.length >= MAX_TAPS_PER_SECOND) return;
        recentTapTimes.push(tapNow);

        initAudio();

        // Координаты тапа относительно монеты
        const rect = dom.coin.getBoundingClientRect();
        const clientX = e.clientX || (e.touches && e.touches[0].clientX) || (rect.left + rect.width / 2);
        const clientY = e.clientY || (e.touches && e.touches[0].clientY) || (rect.top + rect.height / 2);
        spawnTapCrown(clientX, clientY, tapNow);

        // Расчет 3D-наклона в сторону нажатия
        const offsetX = (clientX - (rect.left + rect.width / 2)) / (rect.width / 2);
        const offsetY = (clientY - (rect.top + rect.height / 2)) / (rect.height / 2);
        dom.coin.style.transform = `scale(0.93) rotateX(${-offsetY * 18}deg) rotateY(${offsetX * 18}deg)`;
        setTimeout(() => {
            dom.coin.style.transform = '';
        }, 120);

        // Расчет критического удара (шанс 2%, в fever 7% + бонус скина + Око Судьбы + Дракон)
        const skin = getActiveSkin();
        const eyeLvl = (GameState.artifacts && GameState.artifacts.eye_destiny) || 0;
        let critChance = feverActive ? 0.07 : 0.02;
        if (skin.critChanceBonus) critChance += skin.critChanceBonus;
        if (eyeLvl > 0) critChance += eyeLvl * 0.02;

        let critMult = 5 + (eyeLvl * 2);
        const activePet = getActivePet();
        if (activePet && activePet.id === 'dragon') {
            const dragonLvl = getPetLevel('dragon');
            critChance += 0.02 + dragonLvl * 0.01;
            critMult += dragonLvl * 2;
        }

        const isCrit = Math.random() < critChance;

        let gain = getClickPower();
        if (isCrit) {
            gain *= critMult;
            GameState.totalCrits++;
        }

        // Питомец Единорог: 15% шанс удвоить силу тапа
        if (activePet && activePet.id === 'unicorn' && Math.random() < 0.15) {
            gain *= 2;
        }

        // Начисление монет
        GameState.score += gain;
        GameState.totalEarned += gain;
        GameState.runCoinsEarned = (GameState.runCoinsEarned || 0) + gain;
        GameState.totalClicks++;

        // Учёт задания по кликам
        trackQuestProgress('clicks', 1);

        // Звук
        playSound(isCrit ? 'crit' : 'click');

        // Визуальные эффекты в точке клика
        const layerRect = dom.tapFxLayer.getBoundingClientRect();
        const fxX = clientX - layerRect.left;
        const fxY = clientY - layerRect.top;
        spawnTapPopup(fxX, fxY, gain, isCrit, critMult);
        spawnTapParticles(fxX, fxY);

        // Увеличение комбо (Fever)
        addFever();

        // Счёт обновляем сразу, остальной интерфейс — в игровом цикле
        if (dom.score) dom.score.textContent = formatNumber(GameState.score);
        checkAchievements();
    }

    // --- ЛИХОРАДКА / FEVER MODE ---
    function addFever() {
        // Если идет 30-секундный кулдаун - комбо заблокировано
        if (Date.now() < feverCooldownUntil) return;
        // Если уже активен режим 3x - клики НЕ могут продлевать таймер (таймер строго 15с)
        if (feverActive) return;

        // Сбалансированный прирост: +2.8% за клик (набирается за ~36 кликов)
        feverValue = Math.min(100, feverValue + 2.8);
        if (feverValue >= 100) {
            activateFever();
        }
    }

    // Длительность «Огонь x3»: 15 с база, +35% со скином Адская Магма, +30% за ур. артефакта Огненное Сердце
    let feverDuration = 15;
    function getFeverDuration(base) {
        let d = base || 15;
        const skin = getActiveSkin();
        if (skin && skin.feverBonus) d *= (1 + skin.feverBonus);
        const heartLvl = (GameState.artifacts && GameState.artifacts.heart_fire) || 0;
        if (heartLvl > 0) d *= (1 + heartLvl * 0.30);
        if (hasHeavenlyUpgrade('fever_eternal')) d *= 1.5; // Вечное Пламя
        d *= ruleEff('fever'); // Правило дня
        return d;
    }

    // fromWheel: награда колеса — сбрасывает перезарядку комбо и всегда включает огонь
    function activateFever(baseSeconds, fromWheel) {
        if (fromWheel) feverCooldownUntil = 0;
        feverActive = true;
        feverDuration = getFeverDuration(baseSeconds || 15);
        feverTimeLeft = feverDuration;
        feverValue = 100;
        trackQuestProgress('feversActivated', 1);
        if (dom.feverBar) {
            dom.feverBar.classList.remove('cooling');
            dom.feverBar.classList.add('active');
        }
        showToast(`🔥 ОГОНЬ x3 НА ${Math.round(feverDuration)} СЕКУНД!`);
        playSound('crit');
    }

    function updateFever(deltaSeconds) {
        // 1. Проверка 30-секундной перезарядки после 3x
        if (Date.now() < feverCooldownUntil) {
            feverActive = false;
            feverValue = 0;
            if (dom.feverBar) {
                dom.feverBar.classList.remove('active');
                dom.feverBar.classList.add('cooling');
            }
            const cdSec = Math.max(0, Math.ceil((feverCooldownUntil - Date.now()) / 1000));
            const pct = (cdSec / 30) * 100;
            if (dom.feverFill) dom.feverFill.style.width = `${pct}%`;
            if (dom.feverText) dom.feverText.textContent = `⏳ Перезарядка (${cdSec}с)`;
            const fcc = document.querySelector('.fever-container');
            if (fcc) fcc.classList.remove('fever-idle');
            return;
        }

        if (dom.feverBar && dom.feverBar.classList.contains('cooling')) {
            dom.feverBar.classList.remove('cooling');
        }

        // 2. Активный режим x3
        if (feverActive) {
            // Таймер строго 15 секунд и непрерывно убывает
            feverTimeLeft -= deltaSeconds;
            feverValue = Math.max(0, (feverTimeLeft / feverDuration) * 100);

            if (dom.feverFill) dom.feverFill.style.width = `${feverValue}%`;
            if (dom.feverText) dom.feverText.textContent = `🔥 Огонь x3 (${Math.max(1, Math.ceil(feverTimeLeft))}с)`;

            if (feverTimeLeft <= 0) {
                // 15 секунд истекли -> запускаем 30-секундный ресет/кулдаун
                feverActive = false;
                feverValue = 0;
                feverCooldownUntil = Date.now() + 30000; // 30 секунд ресета
                if (dom.feverBar) {
                    dom.feverBar.classList.remove('active');
                    dom.feverBar.classList.add('cooling');
                }
                showToast('⏳ «Огонь x3» закончился. Перезарядка 30 сек.');
            }
        } else {
            // 3. Обычное накопление: естественное мягкое убывание 6.0/сек
            feverValue = Math.max(0, feverValue - deltaSeconds * 6.0);
            const fw = `${Math.round(feverValue * 2) / 2}%`;
            if (dom.feverFill && dom.feverFill.__w !== fw) { dom.feverFill.__w = fw; dom.feverFill.style.width = fw; }

            let multiplier = 'x1';
            if (feverValue >= 70) multiplier = 'x1.5';
            else if (feverValue >= 35) multiplier = 'x1.2';
            setText(dom.feverText, `🔥 Комбо ${multiplier}`);
        }
        // Полоска комбо видна, только пока игрок тапает (или идёт «Огонь» / перезарядка)
        const fc = document.querySelector('.fever-container');
        if (fc) fc.classList.toggle('fever-idle', !feverActive && feverValue <= 0.5 && Date.now() >= feverCooldownUntil);
    }

    // --- ЛЕТАЮЩИЙ СЛУЧАЙНЫЙ БОНУС (как золотое печенье Cookie Clicker: раз в 5–15 минут) ---
    const BONUS_MIN_INTERVAL = 5 * 60000;   // 5 минут
    const BONUS_MAX_INTERVAL = 15 * 60000;  // 15 минут
    const BONUS_MAX_SPEEDUP = 0.5;          // улучшения ускоряют максимум в 2 раза
    // Первая комета пораньше (1.5–3 мин), чтобы новый игрок с ней познакомился
    let nextBonusTime = Date.now() + 90000 + Math.random() * 90000;
    const bonusFlight = {
        active: false,
        startX: 0,
        startY: 0,
        endX: 0,
        endY: 0,
        duration: 8000,
        startTime: 0,
        waveFreq: 2.5,
        waveAmp: 25
    };

    function checkFloatingBonus() {
        if (!bonusFlight.active && Date.now() > nextBonusTime) {
            startBonusFlight();
            const skin = getActiveSkin();
            let intervalMult = 1.0;
            const luckLvl = getHeavenlyUpgradeLevel('heavenly_luck');
            if (luckLvl > 0) intervalMult *= 1 - Math.min(5, luckLvl) * 0.06; // −6% ожидания за уровень (до −30%)
            if (hasHeavenlyUpgrade('serendipity')) intervalMult *= 0.7; // ещё −30%
            if (skin && skin.giftBonus) intervalMult /= (1 + skin.giftBonus); // Пиратский Дублон
            if (GameState.pact === 'light') intervalMult *= 0.85; // Светлый путь: кометы на 15% чаще
            if (hasOneTime('comet_lucky_day')) intervalMult *= 0.85;
            if (hasOneTime('comet_horseshoe')) intervalMult *= 0.85;
            intervalMult *= getTempleCometMult(); // Совет: Хранитель Удачи
            intervalMult *= decreeMult('comet'); // Указы императора
            intervalMult *= ruleEff('comet'); // Правило дня
            intervalMult /= 1 + mayorLvl('tech') * 0.04; // Мэр Техно-квартала
            intervalMult *= getChallengeRewardMult('comet'); // награда за «Блиц»
            if (isWeekend()) intervalMult *= 0.7; // Ярмарка выходных: кометы на 30% чаще
            intervalMult = Math.max(BONUS_MAX_SPEEDUP, intervalMult);
            const baseInterval = BONUS_MIN_INTERVAL + Math.random() * (BONUS_MAX_INTERVAL - BONUS_MIN_INTERVAL);
            nextBonusTime = Date.now() + Math.floor(baseInterval * intervalMult);
        }
    }

    function startBonusFlight(forcedType) {
        const arena = document.getElementById('tap-arena');
        if (!arena) return;
        const rect = arena.getBoundingClientRect();

        const fromLeft = Math.random() > 0.5;
        const width = rect.width || 400;
        const height = rect.height || 350;

        bonusFlight.startX = fromLeft ? -80 : width + 80;
        bonusFlight.endX = fromLeft ? width + 80 : -80;
        bonusFlight.startY = 50 + Math.random() * Math.max(80, height - 140);
        bonusFlight.endY = 50 + Math.random() * Math.max(80, height - 140);
        bonusFlight.startTime = performance.now();
        bonusFlight.duration = 7500 + Math.random() * 2000;
        bonusFlight.waveFreq = 2 + Math.random() * 1.5;
        bonusFlight.waveAmp = 20 + Math.random() * 20;
        bonusFlight.active = true;

        // Определение типа кометы: Золотая (70%) или Багровое Затмение (30%)
        // Тёмные кометы (с риском потерь) появляются только у опытных игроков
        bonusFlight.type = forcedType || (GameState.pact === 'dark' && Math.random() < 0.30 ? 'wrath' : 'golden');
        if (dom.floatingBonus) {
            dom.floatingBonus.classList.remove('bonus-golden', 'bonus-wrath');
            dom.floatingBonus.classList.add(bonusFlight.type === 'wrath' ? 'bonus-wrath' : 'bonus-golden');
            dom.floatingBonus.classList.remove('hidden');
        }
        // Вид кометы: золотая, тёмная или сезонная (тыква, ёлочный шар, сердце, яйцо, солнце)
        {
            const season = getActiveSeason();
            const kind = bonusFlight.type === 'wrath' ? 'dark' : (season ? season.id : 'gold');
            const head = document.getElementById('comet-head');
            if (head) head.src = `assets/icons/comet_${kind}.svg`;
            if (dom.floatingBonus) dom.floatingBonus.setAttribute('data-kind', kind);
            bonusFlight.lastX = null; bonusFlight.lastY = null;
            cometTrailClear();
        }

        // Артефакт: Магический Сачок (50% шанс авто-поимки)
        if (GameState.artifacts && GameState.artifacts.magic_net && Math.random() < 0.5) {
            setTimeout(() => {
                if (bonusFlight.active) {
                    showToast('🕸️ Магический Сачок поймал комету за вас!');
                    onFloatingBonusClick();
                }
            }, 1200);
        }

        // Питомец: Дрон-Добытчик (60% шанс авто-поимки)
        const pet = getActivePet();
        if (pet && pet.id === 'drone' && Math.random() < 0.6) {
            setTimeout(() => {
                if (bonusFlight.active) {
                    triggerPetSpeech('🤖 Дрон перехватил комету!');
                    onFloatingBonusClick();
                }
            }, 1600);
        }
    }

    function updateBonusFlight(now) {
        if (!bonusFlight.active) return;
        const elapsed = now - bonusFlight.startTime;
        const progress = elapsed / bonusFlight.duration;

        if (progress >= 1) {
            bonusFlight.active = false;
            dom.floatingBonus.classList.add('hidden');
            cometTrailClear();
            return;
        }

        const curX = bonusFlight.startX + (bonusFlight.endX - bonusFlight.startX) * progress;
        const curY = bonusFlight.startY + (bonusFlight.endY - bonusFlight.startY) * progress + Math.sin(progress * Math.PI * bonusFlight.waveFreq * 2) * bonusFlight.waveAmp;

        dom.floatingBonus.style.left = `${curX}px`;
        dom.floatingBonus.style.top = `${curY}px`;
        // Хвост кометы — плавный шлейф по настоящей траектории полёта
        cometTrailDraw(curX + 31, curY + 31, now);
        bonusFlight.lastX = curX; bonusFlight.lastY = curY;
    }

    // ---- Шлейф кометы: canvas поверх арены, сужающаяся светящаяся лента по последним точкам пути ----
    const COMET_TRAIL_COLORS = { gold: [255, 200, 70], dark: [167, 110, 250], halloween: [251, 130, 50], newyear: [110, 200, 255], valentine: [251, 100, 130], spring: [236, 120, 200], summer: [250, 200, 30] };
    const cometTrail = { cv: null, ctx: null, pts: [], w: 0, h: 0, dpr: 1 };
    function cometTrailCanvas() {
        if (cometTrail.cv) return cometTrail.cv;
        const host = dom.floatingBonus && dom.floatingBonus.parentElement;
        if (!host) return null;
        const cv = document.createElement('canvas');
        cv.id = 'comet-trail';
        host.insertBefore(cv, dom.floatingBonus);
        cometTrail.cv = cv; cometTrail.ctx = cv.getContext('2d');
        return cv;
    }
    function cometTrailClear() {
        cometTrail.pts.length = 0;
        if (cometTrail.ctx) cometTrail.ctx.clearRect(0, 0, cometTrail.cv.width, cometTrail.cv.height);
    }
    function cometTrailDraw(x, y, now) {
        const cv = cometTrailCanvas();
        if (!cv) return;
        const host = cv.parentElement;
        const w = host.clientWidth, h = host.clientHeight;
        const dpr = Math.min(2, window.devicePixelRatio || 1);
        if (w !== cometTrail.w || h !== cometTrail.h || dpr !== cometTrail.dpr) {
            cometTrail.w = w; cometTrail.h = h; cometTrail.dpr = dpr;
            cv.width = Math.round(w * dpr); cv.height = Math.round(h * dpr);
        }
        const pts = cometTrail.pts;
        // точку добавляем, только когда комета сместилась; хвост держим постоянной длины по пути
        // последняя точка — «голова» (двигается каждый кадр); закрепляем её, когда отошла от предыдущей закреплённой
        const n0 = pts.length;
        if (n0 < 2) pts.push({ x, y, t: now });
        else {
            const head = pts[n0 - 1], prev = pts[n0 - 2];
            if (Math.hypot(head.x - prev.x, head.y - prev.y) > 3) pts.push({ x, y, t: now });
            else { head.x = x; head.y = y; head.t = now; }
        }
        const LEN = 130; // px — длина хвоста
        let total = 0;
        for (let i = pts.length - 1; i > 0; i--) {
            total += Math.hypot(pts[i].x - pts[i - 1].x, pts[i].y - pts[i - 1].y);
            if (total > LEN) { pts.splice(0, i - 1); break; }
        }
        const ctx = cometTrail.ctx;
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        ctx.clearRect(0, 0, w, h);
        if (pts.length < 3) return;
        const kind = (dom.floatingBonus.getAttribute('data-kind')) || 'gold';
        const [r, g, b] = COMET_TRAIL_COLORS[kind] || COMET_TRAIL_COLORS.gold;
        const low = document.body.classList.contains('low-fx');
        const n = pts.length;
        // сглаженные точки (скользящее среднее), чтобы лента не ломалась на изгибах
        const sm = pts.map((p, i) => {
            const a = pts[Math.max(0, i - 2)], b = pts[Math.min(n - 1, i + 2)], c = pts[Math.max(0, i - 1)], d = pts[Math.min(n - 1, i + 1)];
            return i === n - 1 ? p : { x: (a.x + b.x + c.x + d.x + p.x) / 5, y: (a.y + b.y + c.y + d.y + p.y) / 5 };
        });
        // сужающаяся лента одним многоугольником — без «бусин» от перекрытия отрезков
        const ribbon = (maxW) => {
            const L = [], R = [];
            for (let i = 0; i < n; i++) {
                const p = sm[i], q = sm[Math.min(n - 1, i + 1)], o = sm[Math.max(0, i - 1)];
                let dx = q.x - o.x, dy = q.y - o.y; const len = Math.hypot(dx, dy) || 1; dx /= len; dy /= len;
                const k = i / (n - 1), hw = maxW * 0.5 * Math.pow(k, 0.75);
                L.push([p.x - dy * hw, p.y + dx * hw]); R.push([p.x + dy * hw, p.y - dx * hw]);
            }
            ctx.beginPath();
            ctx.moveTo(L[0][0], L[0][1]);
            for (let i = 1; i < n; i++) ctx.lineTo(L[i][0], L[i][1]);
            const h = sm[n - 1]; // круглая «шапка» у головы
            ctx.arc(h.x, h.y, Math.hypot(L[n - 1][0] - h.x, L[n - 1][1] - h.y), Math.atan2(L[n - 1][1] - h.y, L[n - 1][0] - h.x), Math.atan2(R[n - 1][1] - h.y, R[n - 1][0] - h.x), true);
            for (let i = n - 1; i >= 0; i--) ctx.lineTo(R[i][0], R[i][1]);
            ctx.closePath();
        };
        const t0 = sm[0], t1 = sm[n - 1];
        const grad = (rgb, a) => {
            const gr = ctx.createLinearGradient(t0.x, t0.y, t1.x, t1.y);
            gr.addColorStop(0, `rgba(${rgb},0)`); gr.addColorStop(0.55, `rgba(${rgb},${(a * 0.45).toFixed(3)})`); gr.addColorStop(1, `rgba(${rgb},${a})`);
            return gr;
        };
        const col = `${r},${g},${b}`;
        if (!low) { ribbon(58); ctx.fillStyle = grad(col, 0.22); ctx.fill(); }
        ribbon(34); ctx.fillStyle = grad(col, 0.75); ctx.fill();
        if (!low) { ribbon(12); ctx.fillStyle = grad('255,248,225', 0.8); ctx.fill(); }
        // искорки вдоль хвоста
        if (!low) {
            for (let i = 2; i < n - 2; i += 3) {
                const k = i / (n - 1), p = pts[i];
                const tw = 0.5 + 0.5 * Math.sin(p.t * 0.05 + i);
                ctx.fillStyle = `rgba(255,255,255,${(0.75 * k * tw).toFixed(3)})`;
                ctx.beginPath(); ctx.arc(p.x + Math.sin(p.t * 0.013 + i) * 6 * (1 - k), p.y + Math.cos(p.t * 0.017 + i) * 6 * (1 - k), 1 + 1.4 * k, 0, Math.PI * 2); ctx.fill();
            }
        }
    }

    function onFloatingBonusClick() {
        if (!bonusFlight.active) return;

        // Координаты для взрыва конфетти
        const bonusRect = dom.floatingBonus.getBoundingClientRect();
        const layerRect = dom.tapFxLayer.getBoundingClientRect();
        const fxX = bonusRect.left + bonusRect.width / 2 - layerRect.left;
        const fxY = bonusRect.top + bonusRect.height / 2 - layerRect.top;

        const isWrath = bonusFlight.type === 'wrath';
        bonusFlight.active = false;
        dom.floatingBonus.classList.add('hidden');
        if (hasHeavenlyUpgrade('comet_storm') && Math.random() < 0.15) { // Звездопад: следом летит ещё одна комета
            nextBonusTime = Date.now() + 2500;
            setTimeout(() => showToast('☄️ Звездопад! Следом летит ещё одна комета!'), 900);
        }
        cometTrailClear();
        playSound('comet');

        // Взрыв конфетти!
        spawnConfetti(fxX, fxY);

        GameState.totalGiftsCaught++;
        trackQuestProgress('bonusesCaught', 1);
        trackQuestProgress('cometsCaught', 1);

        if (isWrath) {
            // ЭФФЕКТЫ ГНЕВНОЙ КОМЕТЫ ЗАТМЕНИЯ (Cookie Clicker Wrath Cookie)
            const wRoll = Math.random();
            if (wRoll < 0.10) {
                // 10% шанс: Багровое безумие x555 ко всему доходу на 6 сек (как в Cookie Clicker)
                const dur = 6000;
                GameState.elderFrenzyActiveUntil = Math.max(Date.now(), GameState.elderFrenzyActiveUntil || 0) + dur;
                playSound('crit');
                showToast(`🔴 БАГРОВОЕ ЗАТМЕНИЕ: БЕЗУМИЕ x555 на 6 секунд!`);
                spawnTapPopup(fxX, fxY, 0, true, 0, `🔴 БЕЗУМИЕ x555!`);
            } else if (wRoll < 0.38) {
                // 28% шанс: Дар Древних: +1 или +2 кристалла
                const gems = Math.random() < 0.8 ? 1 : 2;
                GameState.prestigeGems += gems;
                showToast(`🔮 ТЁМНЫЙ ДАР: Кристаллы Престижа +${gems} 💎!`);
                spawnTapPopup(fxX, fxY, gems, true, 0, `+${gems} 💎`);
            } else if (wRoll < 0.68) {
                // 30% шанс: Налог Скупости (Инфляция -50% на 25с)
                GameState.clotActiveUntil = Math.max(Date.now(), GameState.clotActiveUntil || 0) + 25000;
                showToast(`❄️ ПРОКЛЯТИЕ ЗАТМЕНИЯ: Инфляция! Доход снижен на 50% на 25 секунд!`);
                spawnTapPopup(fxX, fxY, 0, false, 0, `❄️ ИНФЛЯЦИЯ -50%!`);
            } else {
                // 32% шанс: Коварный клад (50/50: +25% к банку или потеря 8%)
                if (Math.random() < 0.55) {
                    const gain = Math.max(100, Math.floor(GameState.score * 0.25) || Math.floor(getClickPower() * 50));
                    GameState.score += gain;
                    GameState.totalEarned += gain;
                    GameState.runCoinsEarned = (GameState.runCoinsEarned || 0) + gain;
                    showToast(`💀 СДЕЛКА С БЕЗДНОЙ: Ограблен древний склеп! +${formatNumber(gain)} 🪙!`);
                    spawnTapPopup(fxX, fxY, gain, true, 0, `+${formatNumber(gain)} 🪙`);
                } else {
                    const loss = Math.floor(GameState.score * 0.08);
                    GameState.score = Math.max(0, GameState.score - loss);
                    showToast(`🕸️ ДАНЬ ТЬМЕ: Бездне принесено в жертву -${formatNumber(loss)} 🪙!`);
                    spawnTapPopup(fxX, fxY, loss, false, 0, `-${formatNumber(loss)} 🪙`);
                }
            }
            updateUI();
            return;
        }

        // ЭФФЕКТЫ ЗОЛОТОЙ КОМЕТЫ (Cookie Clicker Golden Cookie)
        tryDropSeasonItem(SEASON_DROP_CHANCE);
        const roll = Math.random();
        const getLucky = hasHeavenlyUpgrade('get_lucky');
        // Звёздный Лис: +20% к дарам комет за уровень (длительность безумий и монеты «Счастливчика»)
        const foxK = GameState.selectedPet === 'starfox' ? 1 + getPetLevel('starfox') * 0.2 : 1;
        const frenzyDur = Math.round((getLucky ? 90000 : 45000) * foxK);
        const clickFrenzyDur = Math.round((getLucky ? 26000 : 13000) * foxK);

        if (roll < 0.35) {
            // 35% шанс: Frenzy (Безумие x7 ко всей добыче)
            GameState.frenzyActiveUntil = Math.max(Date.now(), GameState.frenzyActiveUntil || 0) + frenzyDur;
            const sec = Math.round(frenzyDur / 1000);
            showToast(`🔥 ЗОЛОТОЙ ДАР: ДЕНЕЖНОЕ БЕЗУМИЕ! x7 ко всей добыче на ${sec} секунд!`);
            spawnTapPopup(fxX, fxY, 0, false, 0, `🔥 БЕЗУМИЕ x7 (${sec}с)!`);
        } else if (roll < 0.60) {
            // 25% шанс: Click Frenzy (Клик-Безумие x777)
            GameState.clickFrenzyActiveUntil = Math.max(Date.now(), GameState.clickFrenzyActiveUntil || 0) + clickFrenzyDur;
            const sec = Math.round(clickFrenzyDur / 1000);
            showToast(`⚡ ЗОЛОТОЙ ДАР: КЛИК-БЕЗУМИЕ! x777 к силе тапа на ${sec} секунд!`);
            spawnTapPopup(fxX, fxY, 0, false, 0, `⚡ КЛИК x777 (${sec}с)!`);
        } else if (roll < 0.90) {
            // 30% шанс: Lucky (Золотой Куш) - 15% банка или до 15 минут пассивного дохода
            const passive15m = getPassiveIncome() * 900;
            const bank15pct = GameState.score * 0.15;
            let reward = cleanRound(Math.max(100, Math.min(bank15pct + 13, passive15m + 13) || Math.max(100, getClickPower() * 80)));
            if (hasHeavenlyUpgrade('season_switcher')) {
                reward = Math.floor(reward * 1.25);
            }
            if (hasHeavenlyUpgrade('golden_touch')) reward = Math.floor(reward * 1.5); // Золотое Касание
            reward = Math.floor(reward * foxK);
            GameState.score += reward;
            GameState.totalEarned += reward;
            GameState.runCoinsEarned = (GameState.runCoinsEarned || 0) + reward;
            showToast(`🍀 ЗОЛОТОЙ ДАР: СЧАСТЛИВЧИК! +${formatNumber(reward)} монет!`);
            spawnTapPopup(fxX, fxY, reward, false, 0, `+${formatNumber(reward)} 🪙`);
        } else {
            // 10% шанс: Кристальный дар
            let gems = (Math.random() < 0.7 ? 1 : 2) + (hasHeavenlyUpgrade('golden_touch') ? 1 : 0);
            GameState.prestigeGems += gems;
            showToast(`💎 ЗОЛОТОЙ ДАР: Алмазный метеорит! +${gems} кристалл${gems > 1 ? 'а' : ''}!`);
            spawnTapPopup(fxX, fxY, gems, true, 0, `+${gems} 💎`);
        }

        updateUI();
    }

    // ========================================================
    // ПИЯВКИ АПОКАЛИПСИСА (WRINKLERS / ЗОЛОТЫЕ ЖУКИ)
    // ========================================================
    let lastWrinklerSpawn = Date.now();
    const WRINKLERS_MAX = 8;

    // Возврат при лопании растёт с числом жуков на монете: 1 жук = 115%, 8 жуков = 150%
    function getWrinklerReturnMult(count) {
        return 1.10 + 0.05 * Math.max(1, count);
    }

    function spawnWrinkler() {
        if (!GameState.wrinklers) GameState.wrinklers = [];
        if (GameState.wrinklers.length >= WRINKLERS_MAX) return;

        const occupied = GameState.wrinklers.map(w => w.angle);
        let bestAngle = Math.random() * Math.PI * 2;
        let maxDist = -1;

        for (let i = 0; i < 16; i++) {
            const testAngle = (i / 16) * Math.PI * 2;
            let minDist = Math.PI * 2;
            for (const occ of occupied) {
                const diff = Math.abs(testAngle - occ);
                const circDiff = Math.min(diff, Math.PI * 2 - diff);
                if (circDiff < minDist) minDist = circDiff;
            }
            if (minDist > maxDist) {
                maxDist = minDist;
                bestAngle = testAngle;
            }
        }

        GameState.wrinklers.push({
            id: 'w_' + Date.now() + '_' + Math.floor(Math.random() * 1000),
            angle: bestAngle,
            suckedCoins: 0,
            state: 'crawling',
            crawlStart: Date.now(),
            crawlDuration: 3500 // 3.5 секунды ползёт к монете
        });

        renderWrinklers();
        playSound('click');
        showToast('🐛 Замечен Золотой Жук-Паразит! Он ползёт к вашей монете!');
    }

    function renderWrinklers() {
        if (!dom.wrinklersLayer) return;
        const list = GameState.wrinklers || [];
        const count = list.length;

        if (dom.btnPopWrinklers) {
            dom.btnPopWrinklers.classList.toggle('hidden', count === 0);
            if (dom.wrinklersCount) dom.wrinklersCount.textContent = count;
        }

        // Элементы переиспользуются по id жука: позиции обновляются, а не создаются заново.
        // Иначе пока один жук ползёт, слой перерисовывался каждый кадр и клики по остальным терялись.
        const existing = {};
        dom.wrinklersLayer.querySelectorAll('.wrinkler-bug').forEach(el => { existing[el.getAttribute('data-wid')] = el; });
        const alive = new Set();

        const coinRadius = (dom.coin && dom.coin.offsetWidth) ? dom.coin.offsetWidth / 2 : 95;
        const cx = 125, cy = 125, targetRadius = coinRadius + 9;
        const now = Date.now();

        list.forEach((w, idx) => {
            if (!w.id) w.id = 'w_' + idx + '_' + Math.floor(Math.random() * 100000);
            alive.add(w.id);
            let radius = targetRadius;
            let isCrawling = false;
            if (w.state === 'crawling') {
                const elapsed = now - (w.crawlStart || now);
                const progress = Math.min(1, elapsed / (w.crawlDuration || 3500));
                if (progress >= 1) {
                    w.state = 'attached';
                } else {
                    isCrawling = true;
                    const startRadius = 260;
                    radius = startRadius - (startRadius - targetRadius) * progress;
                }
            }

            const x = cx + Math.cos(w.angle) * radius - 19;
            const y = cy + Math.sin(w.angle) * radius - 19;
            const deg = (w.angle * 180 / Math.PI) - 90; // головой к центру монеты

            let el = existing[w.id];
            if (!el) {
                el = document.createElement('div');
                el.className = 'wrinkler-bug';
                el.setAttribute('data-wid', w.id);
                const gid = 'wg_' + String(w.id).replace(/[^a-zA-Z0-9_]/g, '');
                // Золотой жук-скарабей (рисунок головой вверх)
                el.innerHTML = `<img class="wrinkler-svg" src="assets/icons/bug_scarab.svg" alt="" draggable="false">`;
                dom.wrinklersLayer.appendChild(el);
            }
            el.setAttribute('data-index', idx);
            el.classList.toggle('crawling', isCrawling);
            el.style.left = `${x}px`;
            el.style.top = `${y}px`;
            el.style.transform = `rotate(${deg}deg)`;
            el.style.setProperty('--bug-rot', `rotate(${deg}deg)`);
            el.title = isCrawling
                ? `Жук #${idx + 1}: ползёт к монете... Подождите, пока присосётся!`
                : `Жук #${idx + 1}: накоплено ${formatNumber(Math.floor((w.suckedCoins || 0) * getWrinklerReturnMult(count)))} 🪙 (+${Math.round((getWrinklerReturnMult(count) - 1) * 100)}% прибыли — чем больше жуков, тем выгоднее!). Нажмите, чтобы лопнуть!`;
        });

        for (const wid in existing) {
            if (!alive.has(wid)) existing[wid].remove();
        }
    }

    function popWrinkler(idx, clientX, clientY) {
        if (!GameState.wrinklers || !GameState.wrinklers[idx]) return;
        const w = GameState.wrinklers[idx];
        if (w.state === 'crawling') {
            showToast('🐜 Жук ещё ползёт к монете! Подождите, пока он присосётся!');
            return;
        }

        const raw = w.suckedCoins || 0;
        const retMult = getWrinklerReturnMult(GameState.wrinklers.length);
        const retPct = Math.round((retMult - 1) * 100);
        const payout = cleanRound(Math.max(10, Math.floor(raw * retMult)) + Math.floor(getClickPower() * 5));

        GameState.score += payout;
        GameState.totalEarned += payout;
        GameState.runCoinsEarned = (GameState.runCoinsEarned || 0) + payout;
        GameState.wrinklers.splice(idx, 1);
        trackQuestProgress('wrinklersPopped', 1);
        const seasonNow = getActiveSeason();
        if (seasonNow && seasonNow.id === 'halloween') tryDropSeasonItem(0.20);

        playSound('bonus');
        const posX = clientX || window.innerWidth / 2;
        const posY = clientY || window.innerHeight / 2;
        spawnConfetti(posX, posY);
        spawnTapPopup(posX, posY, payout, true, 0, `💥 +${100 + retPct}% ВЕРНУЛОСЬ! +${formatNumber(payout)} 🪙`);
        showToast(`💥 Жук лопнул! Возвращено +${formatNumber(payout)} 🪙 (+${retPct}% прибыли!)`);

        renderWrinklers();
        updateUI();
    }

    function popAllWrinklers() {
        if (!GameState.wrinklers || GameState.wrinklers.length === 0) return;
        const count = GameState.wrinklers.length;
        let totalRaw = 0;
        for (const w of GameState.wrinklers) {
            totalRaw += (w.suckedCoins || 0);
        }
        const retMult = getWrinklerReturnMult(count);
        const payout = cleanRound(Math.max(20, Math.floor(totalRaw * retMult)) + Math.floor(getClickPower() * 10 * count));
        GameState.score += payout;
        GameState.totalEarned += payout;
        GameState.runCoinsEarned = (GameState.runCoinsEarned || 0) + payout;
        GameState.wrinklers = [];
        trackQuestProgress('wrinklersPopped', count);

        playSound('bonus');
        spawnConfetti(window.innerWidth / 2, window.innerHeight / 2);
        spawnTapPopup(window.innerWidth / 2, window.innerHeight / 2, payout, true, 0, `💥 ВСЕ ${count} ЖУКОВ! +${formatNumber(payout)} 🪙`);
        showToast(`💥 Вскрыто ${count} жуков! Возвращено +${formatNumber(payout)} 🪙 с бонусом +${Math.round((retMult - 1) * 100)}%!`);

        renderWrinklers();
        updateUI();
    }

