    function openShop() {
        renderShop();
        const m = document.getElementById('modal-shop');
        if (m) { m.classList.remove('hidden'); modalFx(m, 'ui_shop', 'shop', '.shop-hero-title, .shop-hero-sub, #shop-body > *, #shop-body .shop-row-card, #shop-body .shop-gem-card'); }
    }

    // ========================================================
    // НАГРАДА ЗА ВХОД (календарь на 7 дней). Одна награда за календарный день; пропуск дней НЕ сбрасывает —
    // зашёл через 2 дня — получаешь награду следующего дня по счёту.
    // ========================================================
    // 30 дней: награды растут, на 7/14/21 день — большие подарки, на 30-й — сундук. Потом календарь идёт заново.
    const LOGIN_DAYS = 30;
    const LR = (kind, o) => Object.assign({ kind }, o);
    const LOGIN_REWARDS = [
        LR('coins', { minutes: 15 }), LR('gems', { amount: 2 }), LR('coins', { minutes: 30 }), LR('spheres', { amount: 1 }), LR('boost', { minutes: 15 }), LR('coins', { minutes: 60 }),
        LR('grand', { gems: 5, spheres: 2 }),
        LR('coins', { minutes: 60 }), LR('gems', { amount: 3 }), LR('spheres', { amount: 2 }), LR('boost', { minutes: 30 }), LR('coins', { minutes: 120 }), LR('gems', { amount: 4 }),
        LR('grand', { gems: 8, spheres: 3, chips: 1 }),
        LR('coins', { minutes: 120 }), LR('gems', { amount: 4 }), LR('spheres', { amount: 3 }), LR('boost', { minutes: 45 }), LR('coins', { minutes: 180 }), LR('gems', { amount: 5 }),
        LR('grand', { gems: 10, spheres: 4, chips: 2 }),
        LR('coins', { minutes: 180 }), LR('gems', { amount: 6 }), LR('spheres', { amount: 4 }), LR('boost', { minutes: 60 }), LR('coins', { minutes: 240 }), LR('gems', { amount: 8 }), LR('spheres', { amount: 5 }), LR('coins', { minutes: 360 }),
        LR('mega', { gems: 30, spheres: 10, chips: 5, minutes: 240 })
    ].map((r, i) => Object.assign(r, { day: i + 1 }));
    function loginRewardText(r) {
        const h = (m) => m >= 60 ? `${m / 60} ч` : `${m} мин`;
        if (r.kind === 'coins') return `🪙 ${h(r.minutes)}`;
        if (r.kind === 'gems') return `+${r.amount} 💎`;
        if (r.kind === 'spheres') return `+${r.amount} 🔮`;
        if (r.kind === 'boost') return `x2 ${h(r.minutes)}`;
        return `+${r.gems} 💎 +${r.spheres} 🔮${r.chips ? ` +${r.chips} 🌟` : ''}`;
    }

    function localDateStr(d) {
        const x = d || new Date();
        return `${x.getFullYear()}-${String(x.getMonth() + 1).padStart(2, '0')}-${String(x.getDate()).padStart(2, '0')}`;
    }

    function getLoginState() {
        const today = localDateStr();
        const y = new Date(); y.setDate(y.getDate() - 1);
        const yesterday = localDateStr(y);
        const claimedToday = GameState.lastLoginClaim === today;
        const nextDay = (GameState.loginStreak % LOGIN_DAYS) + 1; // пропуск дней не сбрасывает серию
        const currentDay = claimedToday ? (((GameState.loginStreak - 1) % LOGIN_DAYS) + 1) : nextDay;
        return { claimedToday, nextDay, currentDay };
    }

    function claimLoginReward(mult) {
        const st = getLoginState();
        if (st.claimedToday) return;
        passAddXp(25, false);
        const k = mult === 2 ? 2 : 1;
        const r = LOGIN_REWARDS[st.nextDay - 1];
        let msg = '';
        if (r.kind === 'coins') {
            const coins = cleanRound(Math.max(r.minutes * 50, r.minutes * 60 * getRewardIncomePerSec()) * k);
            GameState.score += coins;
            GameState.totalEarned += coins;
            GameState.runCoinsEarned = (GameState.runCoinsEarned || 0) + coins;
            msg = `+${formatNumber(coins)} 🪙`;
        } else if (r.kind === 'gems') {
            GameState.prestigeGems += r.amount * k;
            msg = `+${r.amount * k} 💎`;
        } else if (r.kind === 'spheres') {
            GameState.sugarLumps = (GameState.sugarLumps || 0) + r.amount * k;
            msg = `+${r.amount * k} 🔮`;
        } else if (r.kind === 'boost') {
            GameState.boostActiveUntil = Math.max(Date.now(), GameState.boostActiveUntil || 0) + r.minutes * 60000 * k;
            msg = `x2 к доходу на ${r.minutes * k} минут`;
        } else {
            // большой подарок (7/14/21) и сундук 30-го дня
            GameState.prestigeGems += r.gems * k;
            GameState.sugarLumps = (GameState.sugarLumps || 0) + r.spheres * k;
            if (r.chips) GameState.heavenlyChips = (GameState.heavenlyChips || 0) + r.chips * k;
            msg = `+${r.gems * k} 💎 и +${r.spheres * k} 🔮${r.chips ? ` и +${r.chips * k} 🌟` : ''}`;
            if (r.kind === 'mega') {
                const v = gainCoins(incomeMinutes(r.minutes) * k);
                const ex = ext18(); ex.loginMega = (ex.loginMega || 0) + 1;
                setTimeout(() => showLootChest({ title: 'Подарок 30-го дня!', chest: 'assets/icons/x_pass_box.svg', items: [
                    { img: 'assets/icons/cur_coin.svg', text: `+${formatNumber(v)}`, sub: `${r.minutes / 60} ч дохода` },
                    { img: 'assets/icons/cur_gem.svg', text: `+${r.gems * k}`, sub: 'кристаллов' },
                    { img: 'assets/icons/cur_sphere.svg', text: `+${r.spheres * k}`, sub: 'сфер' },
                    { img: 'assets/icons/cur_chip.svg', text: `+${r.chips * k}`, sub: 'небесных звёзд' }] }), 300);
            }
        }
        GameState.loginStreak = (GameState.loginStreak || 0) + 1;
        GameState.lastLoginClaim = localDateStr();
        playSound('bonus');
        spawnConfetti(window.innerWidth / 2, window.innerHeight / 2);
        showToast(`Награда за ${st.nextDay}-й день: ${msg}`, 'ui_daily');
        renderLoginModal();
        updateLoginUI();
        updateUI();
        saveGame();
    }

    function renderLoginModal() {
        const body = document.getElementById('login-modal-body');
        if (!body) return;
        const st = getLoginState();
        const cur = st.claimedToday ? st.currentDay : st.nextDay;
        const toMega = LOGIN_DAYS - cur;
        body.innerHTML = `<div class="login-progress"><b>День ${cur} из ${LOGIN_DAYS}</b><span>${toMega > 0 ? `До большого сундука: ${toMega} дн.` : 'Сегодня — большой сундук!'}</span><div class="login-bar"><i style="width:${cur / LOGIN_DAYS * 100}%"></i></div></div>
        <div class="login-grid login-grid30">${LOGIN_REWARDS.map(r => {
            let cls = 'future';
            if (st.claimedToday ? r.day <= st.currentDay : r.day < st.nextDay) cls = 'done';
            if (!st.claimedToday && r.day === st.nextDay) cls = 'today';
            const big = r.kind === 'mega' ? 'mega' : r.kind === 'grand' ? 'grand' : '';
            const ic = cls === 'done' ? '✅' : r.kind === 'mega' ? artIcon('x_pass_box', '🎁') : r.kind === 'grand' ? artIcon('x_crown', '👑') : r.kind === 'boost' ? artIcon('lg_ad', '🎬') : r.kind === 'gems' ? curIc('gem') : r.kind === 'spheres' ? curIc('sphere') : curIc('coin');
            return `<div class="login-day ${cls} ${big}"><span class="login-day-num">${r.day}</span><span class="login-day-icon">${ic}</span><span class="login-day-text">${icz(loginRewardText(r))}</span></div>`;
        }).join('')}</div>
        <p class="login-note">${st.claimedToday ? 'Награда на сегодня получена. Пропуски дней не сбрасывают прогресс.' : 'Одна награда в день. Пропуски дней не сбрасывают прогресс — календарь просто продолжится.'}</p>`;
        const btnAd = document.getElementById('btn-login-claim-ad');
        if (btnAd) btnAd.classList.toggle('hidden', st.claimedToday);
        const btn = document.getElementById('btn-login-claim');
        if (btn) {
            btn.disabled = st.claimedToday;
            btn.textContent = st.claimedToday ? 'Уже получено сегодня' : `Забрать награду за ${st.nextDay}-й день`;
        }
    }

    function openLoginModal() {
        const m = document.getElementById('modal-login');
        if (!m) return;
        renderLoginModal();
        m.classList.remove('hidden');
        modalFx(m, 'ui_daily', 'login', '.login-title, .login-day, .login-note');
    }

    // ========================================================
    // УВЕДОМЛЕНИЯ — заготовка. Сейчас ничего не отправляет.
    // Когда игра будет на Яндексе и появится способ напоминать игроку (если платформа его даст),
    // подключите отправку в sendReturnReminder(): список готовых напоминаний уже собирается здесь.
    // ========================================================
    function getReturnReminders() {
        const list = [];
        const now = Date.now();
        // Награда за вход: завтра в 00:00
        const tomorrow = new Date(); tomorrow.setHours(24, 0, 0, 0);
        if (isFeatureUnlocked('quests')) list.push({ id: 'login', at: tomorrow.getTime(), text: '📅 Ежедневная награда ждёт! Не прерывайте серию.' });
        // Офлайн-доход заполнится
        const chronoLvl = (GameState.artifacts && GameState.artifacts.chrono_magnet) || 0;
        const maxH = hasHeavenlyUpgrade('eternal_vault') ? 36 : hasHeavenlyUpgrade('deep_astral') ? 24 : 8 + chronoLvl * 2.66;
        list.push({ id: 'offline_full', at: now + maxH * 3600000, text: '💰 Казна империи заполнена — заберите доход!' });
        // Экспедиции: когда вернутся питомцы
        try { expState().slots.forEach((x, i) => { if (x && x.end > now) list.push({ id: 'exp_' + i, at: x.end, text: '🗺️ Экспедиция вернулась с добычей!' }); }); } catch (e) {}
        // Босс: «прилетит» через пару часов отсутствия
        try { if (BOSS_IDS.some(id => isFeatureUnlocked(id))) list.push({ id: 'boss', at: now + 2 * 3600000, text: '👾 Над империей кружит босс — защитите казну!' }); } catch (e) {}
        // Влияние совета восстановилась
        if (isFeatureUnlocked('temple') && GameState.temple && GameState.temple.grace < TEMPLE_MAX_GRACE) {
            list.push({ id: 'grace', at: (GameState.temple.graceAt || now) + TEMPLE_GRACE_MS, text: '🏛️ Влияние восстановилось — можно сменить хранителей.' });
        }
        return list;
    }
    function sendReturnReminder() {
        // Хук: сюда подключается реальная отправка уведомлений. Пока — только список (виден в консоли тестовой сборки).
        if (IS_DEV) { try { console.log('[reminders]', getReturnReminders()); } catch (e) {} }
    }

    // ========================================================
