        GameState.pact = null;
        GameState.pactPrompted = false;
        GameState.seasonItems = {};
        GameState.seasonChoice = 'auto';
        GameState.loginStreak = 0;
        GameState.ext = {};
        GameState.lastLoginClaim = '';
        GameState.market = null;
        GameState.seenTips = {};
        GameState.reviewAsked = false;
        // noAds и starterBought — купленное за деньги не сбрасываем
