        GameState.dailyQuestStats = { clicks: 0, rainCaught: 0, feversActivated: 0, wheelSpins: 0, wrinklersPopped: 0 };
        GameState.weeklyQuestStats = { clicks: 0, upgradesBought: 0, safesCracked: 0, wrinklersPopped: 0, bonusesCaught: 0 };
