    function readLocalSaveData() {
        try {
            const raw = localStorage.getItem('tap_empire_save');
            return raw ? JSON.parse(raw) : null;
        } catch (e) {
            return null;
        }
    }

    function isValidSave(data) {
        return !!(data && typeof data === 'object' && data.totalClicks !== undefined);
    }

    let loadingDone = false;
    function finishLoading() {
        if (loadingDone) return;
        loadingDone = true;
        try { dayRuleCache.t = 0; } catch (e) {}
        try { checkSeasonSkins(true); applyActiveSkin(); updateAutoChip(); } catch (e) {}
        updateUI();
        renderUpgradeLists();
        renderSynergiesList();
        renderArtifactsTree();
        renderPetsList();
        renderQuestsList();
        checkOfflineEarnings();
        refreshUnlocks(true); // по загруженному сейву, без тостов
        unlocksLoaded = true;
        updateOnboarding();
        signalGameReady();
        // экран показываем, когда всё встало на места (без прыжков шторки и монеты при запуске)
        requestAnimationFrame(() => requestAnimationFrame(() => setTimeout(() => document.documentElement.classList.remove('booting'), 60)));
    }

    // Какое сохранение взять: где больше прогресса за всё время (так вход в аккаунт с другого устройства
    // не затрёт большой прогресс маленьким); при равном прогрессе — более свежее. Полный сброс прогресса уважается.
    function pickBetterSave(a, b) {
        const ta = a.lastSaveTime || 0, tb = b.lastSaveTime || 0;
        const ra = (a.ext && a.ext.resetAt) || 0, rb = (b.ext && b.ext.resetAt) || 0;
        if (ra && ra > tb) return a;
        if (rb && rb > ta) return b;
        const pa = (a.totalEarned || 0), pb = (b.totalEarned || 0);
        if (Math.abs(pa - pb) <= Math.max(pa, pb) * 0.01) return ta >= tb ? a : b;
        return pa > pb ? a : b;
    }
    function loadCloudSave() {
        if (!(yandexPlayer && yandexPlayer.getData)) {
            loadLocalSave();
            return;
        }
        yandexPlayer.getData().then(cloud => {
            if (loadingDone) { cloudLate(cloud); return; }
            cloudSaveReady = true; cloudState.ok = true; cloudState.last = Date.now();
            const local = readLocalSaveData();
            const cloudOk = isValidSave(cloud);
            const localOk = isValidSave(local);
            let chosen = null;
            if (cloudOk && localOk) chosen = pickBetterSave(local, cloud); else if (cloudOk) {
                chosen = cloud;
            } else if (localOk) {
                chosen = local;
            }
            if (chosen) {
                try {
                    applyLoadedData(chosen);
                } catch (e) {
                    console.warn('Ошибка применения сохранения:', e);
                }
            }
            finishLoading();
            // Если локальный сейв новее облачного — сразу синхронизируем облако
            if (chosen && chosen === local) saveGame(true);
        }).catch(() => {
            // Облако недоступно: играем с локального сейва, облако не перезаписываем
            loadLocalSave();
            if (IS_VK) setTimeout(cloudRetry, 15000);
        });
    }

    // --- Облачное сохранение: статус и догрузка, если облако ответило не сразу ---
    const cloudState = { ok: false, last: 0, tries: 0 };
    // облако ответило, когда игра уже идёт: больше прогресса здесь — отправляем в облако, больше в облаке — спрашиваем игрока
    function cloudLate(cloud) {
        cloudState.ok = true;
        if (!isValidSave(cloud) || pickBetterSave(readLocalSaveData() || {}, cloud) !== cloud) { cloudSaveReady = true; saveGame(true); return; }
        if (!IS_VK) { cloudSaveReady = true; showToast('☁️ В облаке найден прогресс больше — перезапустите игру, чтобы продолжить с него'); return; }
        offerCloudLoad(cloud);
    }
    function cloudRetry() {
        if (cloudSaveReady || !ysdkInstance || !ysdkInstance.getPlayer || cloudState.tries >= 6) return;
        cloudState.tries++;
        ysdkInstance.getPlayer().then(pl => { yandexPlayer = pl; return pl.getData(); })
            .then(cloud => cloudLate(cloud))
            .catch(() => setTimeout(cloudRetry, 20000));
    }
    function offerCloudLoad(cloud) {
        let m = document.getElementById('modal-cloud');
        if (!m) { m = document.createElement('div'); m.id = 'modal-cloud'; m.className = 'modal-overlay hidden'; document.getElementById('app').appendChild(m); }
        const here = GameState.totalEarned || 0, there = cloud.totalEarned || 0;
        m.innerHTML = `<div class="modal-card cloud-card"><div class="modal-badge">☁️ СОХРАНЕНИЕ</div>
            <h3>Найден прогресс с другого устройства</h3>
            <p class="modal-subtext">На другом устройстве заработано <b>${formatNumber(there)} 🪙</b>, вознесений: <b>${cloud.totalPrestiges || 0}</b>.<br>Здесь: <b>${formatNumber(here)} 🪙</b>, вознесений: <b>${GameState.totalPrestiges || 0}</b>.</p>
            <div class="modal-buttons"><button class="btn-modal btn-primary" data-cl="load">Загрузить прогресс</button><button class="btn-modal btn-secondary" data-cl="keep">Оставить этот</button></div></div>`;
        m.classList.remove('hidden');
        m.onclick = (e) => {
            const b = e.target.closest('[data-cl]'); if (!b) return;
            if (b.dataset.cl === 'load') {
                window.__noSave = true;
                try { localStorage.setItem('tap_empire_save', JSON.stringify(cloud)); } catch (err) {}
                showToast('☁️ Загружаем прогресс…');
                setTimeout(() => location.reload(), 300);
            } else {
                m.classList.add('hidden');
                cloudSaveReady = true; saveGame(true);
                showToast('☁️ Этот прогресс сохранён в облако');
            }
        };
    }
    // кнопка «Синхронизировать» в настройках (VK)
    function cloudSyncNow() {
        if (!ysdkInstance || !ysdkInstance.getPlayer) { showToast('☁️ Облако недоступно вне VK'); return; }
        showToast('☁️ Проверяем облако…');
        ysdkInstance.getPlayer().then(pl => { yandexPlayer = pl; return pl.getData(); }).then(cloud => {
            if (isValidSave(cloud) && pickBetterSave(readLocalSaveData() || {}, cloud) === cloud && (cloud.totalEarned || 0) > (GameState.totalEarned || 0) * 1.01) { offerCloudLoad(cloud); return; }
            cloudSaveReady = true; saveGame(true);
            setTimeout(() => { showToast(cloudState.ok ? '☁️ Прогресс сохранён в облако' : '☁️ Не удалось сохранить — попробуйте позже'); updateCloudStatus(); }, 1500);
        }).catch((e) => { cloudState.ok = false; if (!window.__vkLastErr && e) window.__vkLastErr = String(e.message || e.error_type || JSON.stringify(e)).slice(0, 140); showToast('☁️ Облако не отвечает — попробуйте позже' + (window.__vkLastErr ? ` (${window.__vkLastErr})` : '')); updateCloudStatus(); });
    }
    function updateCloudStatus() {
        const el = document.getElementById('vk-cloud-status'); if (!el) return;
        const t = cloudState.last ? new Date(cloudState.last).toLocaleTimeString('ru-RU', { hour: '2-digit', minute: '2-digit' }) : '';
        el.textContent = cloudSaveReady && cloudState.ok ? `☁️ Облако VK: сохранено${t ? ' в ' + t : ''}` : '☁️ Облако VK: нет связи — прогресс пока только на этом устройстве' + (window.__vkLastErr ? ` · ${window.__vkLastErr}` : '');
        el.classList.toggle('bad', !(cloudSaveReady && cloudState.ok));
    }

    function loadLocalSave() {
        if (loadingDone) return;
        const local = readLocalSaveData();
        if (isValidSave(local)) {
            try {
                applyLoadedData(local);
            } catch (e) {
                console.warn('Ошибка применения сохранения:', e);
            }
        }
        finishLoading();
    }

    function applyLoadedData(data) {
        if (data.score !== undefined) GameState.score = data.score;
        if (data.totalEarned !== undefined) GameState.totalEarned = data.totalEarned;
        if (data.runCoinsEarned !== undefined) {
            GameState.runCoinsEarned = data.runCoinsEarned;
        } else {
            GameState.runCoinsEarned = GameState.score || 0;
        }
        if (data.customLayout) GameState.customLayout = data.customLayout;
        if (data.customSticker !== undefined) GameState.customSticker = data.customSticker;
        if (data.totalClicks !== undefined) GameState.totalClicks = data.totalClicks;
        if (data.totalCrits !== undefined) GameState.totalCrits = data.totalCrits;
        if (data.totalGiftsCaught !== undefined) GameState.totalGiftsCaught = data.totalGiftsCaught;
        if (data.totalPrestiges !== undefined) GameState.totalPrestiges = data.totalPrestiges;
        if (data.timePlayedSeconds !== undefined) GameState.timePlayedSeconds = data.timePlayedSeconds;
        if (data.lastSaveTime !== undefined) GameState.lastSaveTime = data.lastSaveTime;
        if (data.megaBoostActiveUntil !== undefined) GameState.megaBoostActiveUntil = data.megaBoostActiveUntil;
        if (data.frenzyActiveUntil !== undefined) GameState.frenzyActiveUntil = data.frenzyActiveUntil;
        if (data.clickFrenzyActiveUntil !== undefined) GameState.clickFrenzyActiveUntil = data.clickFrenzyActiveUntil;
        if (data.lastFreeSpinTime !== undefined) GameState.lastFreeSpinTime = data.lastFreeSpinTime;
        if (data.prestigeGems !== undefined) GameState.prestigeGems = data.prestigeGems;
        if (data.prestigeLevel !== undefined) GameState.prestigeLevel = data.prestigeLevel;
        if (data.heavenlyChips !== undefined) GameState.heavenlyChips = data.heavenlyChips;
        if (data.totalHeavenlyChipsEarned !== undefined) GameState.totalHeavenlyChipsEarned = data.totalHeavenlyChipsEarned;
        if (data.heavenlyUpgrades) Object.assign(GameState.heavenlyUpgrades, data.heavenlyUpgrades);

        // Санитизация чипов от старой формулы (если скопились тысячи чипов без вознесений):
        // (делается один раз для очень старых сохранений: звёзды теперь приходят и из экспедиций, пропуска, ярмарки — их нельзя срезать)
        if ((GameState.heavenlyChips || 0) > 150 && (GameState.prestigeLevel || 0) < 15 && !data.ext) {
            let spentChips = 0;
            for (const upId in (GameState.heavenlyUpgrades || {})) {
                if (GameState.heavenlyUpgrades[upId]) {
                    const up = HEAVENLY_UPGRADES_CONFIG.find(u => u.id === upId);
                    if (up) spentChips += (up.cost || 0);
                }
            }
            let fairEarned = 0;
            for (let l = 0; l < (GameState.prestigeLevel || 0); l++) {
                fairEarned += getAscensionTarget(l).chips;
            }
            GameState.totalHeavenlyChipsEarned = Math.max(spentChips, fairEarned);
            GameState.heavenlyChips = Math.max(0, GameState.totalHeavenlyChipsEarned - spentChips);
        }
        if (data.permSlots) Object.assign(GameState.permSlots, data.permSlots);
        if (GameState.permSlots && GameState.permSlots.slot1 && GameState.permSlots.slot1 === GameState.permSlots.slot2) GameState.permSlots.slot2 = null; // старые сохранения: дубль освобождаем
        if (data.selectedSkin !== undefined) GameState.selectedSkin = data.selectedSkin;
        if (Array.isArray(data.unlockedSkins)) GameState.unlockedSkins = data.unlockedSkins;
        if (data.clickUpgrades) Object.assign(GameState.clickUpgrades, data.clickUpgrades);
        if (data.autoUpgrades) Object.assign(GameState.autoUpgrades, data.autoUpgrades);
        if (data.artifacts) Object.assign(GameState.artifacts, data.artifacts);
        if (data.miniGamesWon !== undefined) GameState.miniGamesWon = data.miniGamesWon;
        if (data.achievementsUnlocked) Object.assign(GameState.achievementsUnlocked, data.achievementsUnlocked);
        if (data.soundEnabled !== undefined) GameState.soundEnabled = data.soundEnabled;
        if (data.sfxVolume !== undefined) GameState.sfxVolume = data.sfxVolume;
        if (data.bgmVolume !== undefined) GameState.bgmVolume = data.bgmVolume;
        if (data.musicEnabled !== undefined) GameState.musicEnabled = data.musicEnabled;
        if (data.showDmgNumbers !== undefined) GameState.showDmgNumbers = data.showDmgNumbers;
        if (data.showParticles !== undefined) GameState.showParticles = data.showParticles;
        if (data.vibrationEnabled !== undefined) GameState.vibrationEnabled = data.vibrationEnabled;
        GameState.weekIndex = typeof data.weekIndex === 'number' ? data.weekIndex : undefined;
        GameState.weekStartEarned = typeof data.weekStartEarned === 'number' && isFinite(data.weekStartEarned) ? data.weekStartEarned : 0;
        GameState.lastSeenVersion = typeof data.lastSeenVersion === 'string' ? data.lastSeenVersion : '';
        GameState.runStats = (data.runStats && typeof data.runStats === 'object') ? data.runStats : null;
        GameState.lastRun = (data.lastRun && typeof data.lastRun === 'object') ? data.lastRun : null;
        GameState.temple = (data.temple && Array.isArray(data.temple.slots)) ? data.temple : null;
        GameState.decreeBuffs = Array.isArray(data.decreeBuffs) ? data.decreeBuffs : [];
        GameState.decreeChains = Array.isArray(data.decreeChains) ? data.decreeChains : [];
        GameState.decreeRecent = Array.isArray(data.decreeRecent) ? data.decreeRecent : [];
        GameState.rulerMercy = +data.rulerMercy || 0;
        GameState.decreesSigned = +data.decreesSigned || 0;
        GameState.decreeChainsDone = +data.decreeChainsDone || 0;
        GameState.dragonsDefeated = +data.dragonsDefeated || 0;
        if (data.featuresSeen && typeof data.featuresSeen === 'object') {
            GameState.featuresSeen = data.featuresSeen;
        } else {
            // Старое сохранение: всё, что было открыто по прежним порогам, остаётся открытым
            GameState.featuresSeen = {};
            const earnedOld = data.totalEarned || 0;
            FEATURE_UNLOCKS.forEach(f => { const at = f.oldAt !== undefined ? f.oldAt : f.at; if (isFinite(at) && earnedOld >= at) GameState.featuresSeen[f.id] = true; });
        }
        GameState.challenge = (data.challenge && typeof data.challenge === 'object') ? data.challenge : null;
        GameState.challengesDone = (data.challengesDone && typeof data.challengesDone === 'object') ? data.challengesDone : {};
        GameState.language = 'ru'; // игра пока только на русском
        if (data.pets) Object.assign(GameState.pets, data.pets);
        if (data.selectedPet) GameState.selectedPet = data.selectedPet;
        if (data.questStats) Object.assign(GameState.questStats, data.questStats);
        if (data.dailyQuestStats) Object.assign(GameState.dailyQuestStats, data.dailyQuestStats);
        if (data.weeklyQuestStats) Object.assign(GameState.weeklyQuestStats, data.weeklyQuestStats);
        if (data.lastDailyDate !== undefined) GameState.lastDailyDate = data.lastDailyDate;
        if (data.lastWeeklyWeek !== undefined) GameState.lastWeeklyWeek = data.lastWeeklyWeek;
        if (data.customDevTheme) Object.assign(GameState.customDevTheme, data.customDevTheme);
        if (data.customLabels) Object.assign(GameState.customLabels, data.customLabels);
        if (data.claimedQuests) Object.assign(GameState.claimedQuests, data.claimedQuests);
        if (data.easterEggsFound) Object.assign(GameState.easterEggsFound, data.easterEggsFound);
        if (Array.isArray(data.purchasedSynergies)) GameState.purchasedSynergies = data.purchasedSynergies;
        if (Array.isArray(data.wrinklers)) GameState.wrinklers = data.wrinklers;
        if (data.sugarLumps !== undefined) GameState.sugarLumps = data.sugarLumps;
        if (data.totalSugarLumpsHarvested !== undefined) GameState.totalSugarLumpsHarvested = data.totalSugarLumpsHarvested;
        if (data.lastSugarLumpTime !== undefined) GameState.lastSugarLumpTime = data.lastSugarLumpTime;
        if (data.buildingSugarLevels) Object.assign(GameState.buildingSugarLevels, data.buildingSugarLevels);
        if (data.grimoireMana !== undefined) GameState.grimoireMana = data.grimoireMana;
        if (data.maxGrimoireMana !== undefined) GameState.maxGrimoireMana = data.maxGrimoireMana;
        if (data.boostActiveUntil !== undefined) GameState.boostActiveUntil = data.boostActiveUntil;
        if (data.elderFrenzyActiveUntil !== undefined) GameState.elderFrenzyActiveUntil = data.elderFrenzyActiveUntil;
        if (data.clotActiveUntil !== undefined) GameState.clotActiveUntil = data.clotActiveUntil;
        if (data.gemsSpent !== undefined) GameState.gemsSpent = data.gemsSpent;
        if (data.tutorialDone !== undefined) GameState.tutorialDone = !!data.tutorialDone;
        GameState.oneTimeUpgrades = (data.oneTimeUpgrades && typeof data.oneTimeUpgrades === 'object') ? data.oneTimeUpgrades : {};
        GameState.pact = (data.pact === 'dark' || data.pact === 'light') ? data.pact : null;
        GameState.seasonItems = (data.seasonItems && typeof data.seasonItems === 'object') ? data.seasonItems : {};
        GameState.loginStreak = data.loginStreak || 0;
        GameState.ext = (data.ext && typeof data.ext === 'object') ? data.ext : {};
        GameState.buyAmount = [1, 10, 100, 'max'].includes(data.buyAmount) ? data.buyAmount : 1;
        GameState.reviewAsked = !!data.reviewAsked;
        GameState.seenTips = (data.seenTips && typeof data.seenTips === 'object') ? data.seenTips : {};
        GameState.noAds = !!data.noAds;
        GameState.starterBought = !!data.starterBought;
        GameState.market = (data.market && typeof data.market === 'object' && data.market.goods) ? data.market : null;
        GameState.lastLoginClaim = data.lastLoginClaim || '';
        GameState.seasonChoice = typeof data.seasonChoice === 'string' ? data.seasonChoice : 'auto';
        GameState.pactPrompted = !!data.pactPrompted;
        // Защита от повреждённого сохранения: NaN / Infinity / отрицательные значения
        ['score', 'totalEarned', 'runCoinsEarned', 'prestigeGems', 'prestigeLevel', 'heavenlyChips', 'totalHeavenlyChipsEarned', 'gemsSpent'].forEach(k => {
            const v = GameState[k];
            if (v !== undefined && (typeof v !== 'number' || !isFinite(v) || v < 0)) GameState[k] = 0;
        });
        [GameState.clickUpgrades, GameState.autoUpgrades].forEach(obj => {
            if (!obj) return;
            for (const k in obj) { const v = obj[k]; if (typeof v !== 'number' || !isFinite(v) || v < 0) obj[k] = 0; else obj[k] = Math.floor(v); }
        });
        applyActiveSkin();
        updatePetCompanionUI();
        renderWrinklers();
        checkQuestsBadge();
        applySavedUiLayout();
    }

    // --- ОФФЛАЙН-ДОХОД (AFK) ---
    let currentOfflineEarned = 0;

    // Письмо «Пока вас не было»: что произошло и что теперь можно сделать
    // Босс, который «прилетел, пока вас не было»: появится после сбора офлайн-дохода
    let returnBossPending = null;
    function maybeReturnBoss() {
        if (!returnBossPending || currentEvent || mgActive) { returnBossPending = null; return; }
        const ev = bossEventById(returnBossPending); returnBossPending = null;
        if (ev) setTimeout(() => { if (!currentEvent && !mgActive) showEventInvite(ev); }, 900);
    }
    function buildOfflineLetter(elapsedSeconds, earned, capped, maxHours) {
        const lines = [];
        // Что произошло, пока игрока не было
        if (capped) lines.push(`🏦 Казна заполнилась до краёв (копится не больше ${Math.round(maxHours)} ч) — заглядывайте чаще или улучшите офлайн-доход в Небесном Древе`);
        try { const n = expReadyCount(); if (n > 0) lines.push(`${artInl('ex_map', '🗺️')} Экспедиция вернулась с добычей${n > 1 ? ` (${n})` : ''} — заберите в «Экспедициях»`); } catch (e) {}
        try { const n = passReadyCount(); if (n > 0 && isFeatureUnlocked('quests')) lines.push(`${artInl('x_pass', '🎟️')} В Имперском пропуске ждут награды: ${n}`); } catch (e) {}
        if (elapsedSeconds >= 3600 && !currentEvent) {
            const open = BOSS_IDS.filter(id => isFeatureUnlocked(id));
            if (open.length) {
                const wb = weekBossId();
                returnBossPending = wb && Math.random() < 0.6 ? wb : open[Math.floor(Math.random() * open.length)];
                lines.push(`${artInl('e_' + returnBossPending, '👾')} Над городом кружит босс — <b>${BOSS_NAMES[returnBossPending]}</b>! Он появится, как только заберёте доход`);
            }
        }
        if ((GameState.tutorialDone || isVeteran()) && !dayRuleActive()) lines.push(`📜 Новое правило дня: «${dayRuleToday().name}» — загляните в «Задания»`);
        const pet = getActivePet();
        const from = pet ? `${artInl(petArt(pet.id), pet.icon)} ${pet.name.replace(/\s*\(.*\)$/, '')}` : '🐱 Кот-Банкир';
        // Сферы копятся и офлайн
        if (isFeatureUnlocked('grimoire') && GameState.lastSugarLumpTime) {
            const sph = Math.floor((Date.now() - GameState.lastSugarLumpTime) / 1000 / ESSENCE_MATURE_TIME);
            if (sph > 0) lines.push(`${curIc('sphere')} Сгустилось Астральных Сфер: <b>+${sph}</b>`);
        }
        // Что теперь по карману
        const budget = (GameState.score || 0) + earned;
        let best = null;
        for (const cfg of AUTO_UPGRADES_CONFIG) {
            const lvl = GameState.autoUpgrades[cfg.id] || 0;
            if (lvl === 0 && best && best.lvl === 0) continue;
            const c = getUpgradeCost(cfg, lvl);
            if (c <= budget && (!best || c > best.cost)) best = { cfg, lvl, cost: c };
        }
        if (best) lines.push(`🏢 Теперь хватит на «${best.cfg.name}»${best.lvl > 0 ? ` (ур. ${best.lvl + 1})` : ' — новое предприятие!'}`);
        // Пропущенные кометы — повод заглядывать чаще
        if (elapsedSeconds >= 1200) {
            const missed = Math.max(1, Math.round(elapsedSeconds / 600));
            lines.push(`☄️ Мимо пролетело комет: ~${missed > 99 ? '99+' : missed}. Ловите их, пока вы в игре!`);
        }
        if (isFeatureUnlocked('quests') && !getLoginState().claimedToday) lines.push(`📅 Ждёт награда за вход — день ${getLoginState().nextDay}`);
        if (isFeatureUnlocked('wheel') && isFreeSpinAvailable()) lines.push('🎡 Колесо Фортуны готово к бесплатному вращению');
        if (isFeatureUnlocked('ascension')) {
            const t = getAscensionTarget(GameState.prestigeLevel || 0);
            const run = (GameState.runCoinsEarned || 0) + earned;
            if (run >= t.reqCoins) lines.push(`${artInl('tab_ascension', '')} Можно вознестись: <b>+${t.chips}</b> ${curIc('chip')} Небесных Звёзд`);
        }
        if (!lines.length) return '';
        return `<div class="offline-letter-from">✉️ Письмо от: ${from}</div><ul>${lines.map(l => `<li>${l}</li>`).join('')}</ul>`;
    }

    function checkOfflineEarnings() {
        if (!GameState.lastSaveTime) return;
        const now = Date.now();
        const elapsedSeconds = (now - GameState.lastSaveTime) / 1000;

        // Офлайн-доход считается БЕЗ временных бустов (x2, x5, x7, x555, комбо)
        const passive = getPassiveIncome(true);
        if (elapsedSeconds > 1 && elapsedSeconds < 30 && passive > 0) {
            // Короткое отсутствие (свернули вкладку на пару секунд) — начисляем тихо
            const quick = Math.floor(elapsedSeconds * passive);
            GameState.score += quick;
            GameState.totalEarned += quick;
            GameState.runCoinsEarned = (GameState.runCoinsEarned || 0) + quick;
        }
        // Если игрока не было более 30 секунд и есть автодоход
        if (elapsedSeconds >= 30 && passive > 0) {
            const chronoLvl = (GameState.artifacts && GameState.artifacts.chrono_magnet) || 0;
            let maxHours = 8 + (chronoLvl * 2.66); // до 16 часов базовая база
            let rate = chronoLvl > 0 ? 1.0 : 0.85; // 100% при chrono_magnet, иначе 85%

            // Небесные улучшения Cookie Clicker
            const gatesLvl = getHeavenlyUpgradeLevel('twin_gates');
            if (hasHeavenlyUpgrade('deep_astral')) {
                maxHours = Math.max(maxHours, 24);
                rate = 1.0;
            } else if (gatesLvl > 0) {
                maxHours = Math.max(maxHours, 4 + gatesLvl * 4);
                rate = Math.max(rate, 0.40 + gatesLvl * 0.12);
            }

            if (hasHeavenlyUpgrade('eternal_vault')) { maxHours = Math.max(maxHours, 36); rate *= 1.5; } // Вечная Казна
            if (trLvl('offline')) rate *= 2; // Сон Вечности
            const maxOfflineSeconds = maxHours * 3600;
            const creditedSeconds = Math.min(elapsedSeconds, maxOfflineSeconds);
            let earned = Math.floor(creditedSeconds * passive * rate);
            // Если окно офлайн-дохода ещё не закрыто — суммируем, а не теряем прошлую сумму
            if (dom.modalOffline && !dom.modalOffline.classList.contains('hidden') && currentOfflineEarned > 0) {
                earned += currentOfflineEarned;
            }

            if (earned > 0) {
                currentOfflineEarned = earned;
                const totalMinutes = Math.floor(creditedSeconds / 60);
                let timeStr = `${Math.floor(creditedSeconds)} сек`;
                if (totalMinutes > 0) {
                    if (totalMinutes < 60) {
                        timeStr = `${totalMinutes} мин`;
                    } else {
                        timeStr = `${Math.floor(totalMinutes / 60)} ч ${totalMinutes % 60} мин`;
                    }
                }

                if (dom.offlineTime) dom.offlineTime.textContent = timeStr;
                if (dom.offlineEarned) dom.offlineEarned.textContent = `+${formatNumber(earned)}`;
                if (dom.offlineBaseAmount) dom.offlineBaseAmount.textContent = `+${formatNumber(earned)}`;
                if (dom.offlineX3Amount) dom.offlineX3Amount.textContent = `+${formatNumber(earned * 3)}`;
                const letterEl = document.getElementById('offline-letter');
                if (letterEl) {
                    let html = '';
                    try { html = buildOfflineLetter(elapsedSeconds, earned, elapsedSeconds > maxOfflineSeconds, maxHours); } catch (e) { html = ''; }
                    letterEl.innerHTML = html;
                    letterEl.classList.toggle('hidden', !html);
                }

                if (dom.modalOffline) {
                    dom.modalOffline.classList.remove('hidden');
                    playSound('bonus');
                }
            }
        }
        GameState.lastSaveTime = now;
    }

    // --- КОЛЕСО ФОРТУНЫ (РУЛЕТКА УДАЧИ) ---
    function cleanRound(val) {
        if (val < 100) return Math.ceil(val / 10) * 10;
        if (val < 1000) return Math.ceil(val / 50) * 50;
        if (val < 10000) return Math.ceil(val / 250) * 250;
        if (val < 100000) return Math.ceil(val / 1000) * 1000;
        const exp = Math.pow(10, Math.floor(Math.log10(val)) - 1);
        return Math.ceil(val / exp) * exp;
    }

    function getWheelBaseScale() {
        const passive = getPassiveIncome(true);
        const click = getClickPower(true);
        // На старте базы хватает на приятные 500-1000 монет, по мере прокачки растет
        return Math.max(500, (passive * 60) || (click * 50));
    }

    function getWheelCoinReward(ratio) {
        let owl = 1;
        const pet = getActivePet();
        if (pet && pet.id === 'owl') owl += 0.25 + getPetLevel('owl') * 0.10;
        return cleanRound(getWheelBaseScale() * ratio * owl);
    }

    const WHEEL_SECTORS = [
        { id: 'gold_mid', ratio: 2.5, name: 'Монеты', icon: '🪙', color: '#e65100', type: 'gold' },
        { id: 'gems_1', label: '+1 💎', name: 'Кристалл', icon: '💎', color: '#6a1b9a', type: 'gems', amount: 1 },
        { id: 'mega', label: 'x5 (3м)', name: 'Мега-режим x5', icon: '⚡', color: '#c62828', type: 'megaboost', duration: 180 },
        { id: 'gold_low', ratio: 1.0, name: 'Монеты', icon: '🪙', color: '#ef6c00', type: 'gold' },
        { id: 'gems_2', label: '+2 💎', name: 'Кристаллы', icon: '💎', color: '#8e24aa', type: 'gems', amount: 2 },
        { id: 'gold_jackpot', ratio: 10.0, name: 'СУПЕР-КУШ', icon: '🎁', color: '#bf360c', type: 'gold' },
        { id: 'fever', label: 'ОГОНЬ 🔥', name: 'Огненный режим', icon: '🔥', color: '#ad1457', type: 'fever', duration: 25 },
        { id: 'gold_high', ratio: 5.0, name: 'Монеты', icon: '🪙', color: '#f57c00', type: 'gold' }
    ];

    let wheelAngle = 0;
    let isWheelSpinning = false;
    let lastPinSector = -1;

    // Нарисованные иконки секторов колеса (рисуются на canvas; пока не загрузились — эмодзи)
    const WHEEL_ICON_FILE = { gold_mid: 'cur_coin', gold_low: 'cur_coin', gold_high: 'cur_coin', gems_1: 'cur_gem', gems_2: 'cur_gem', mega: 'w_bolt', gold_jackpot: 'w_gift', fever: 'w_fire' };
    const wheelIconImgs = {};
    function getWheelIcon(sector) {
        const f = WHEEL_ICON_FILE[sector.id];
        if (!f) return null;
        let img = wheelIconImgs[f];
        if (!img) {
            img = new Image();
            img.onload = () => { img.__ok = true; try { drawWheel(typeof wheelAngle === 'number' ? wheelAngle : 0); } catch (e) {} };
            img.src = `assets/icons/${f}.svg`;
            wheelIconImgs[f] = img;
        }
        return img.__ok ? img : null;
    }
    function drawWheel(angle) {
        if (!dom.wheelCanvas) return;
        const ctx = dom.wheelCanvas.getContext('2d');
        const cx = 280;
        const cy = 280;
        const r = 270;
        const numSectors = WHEEL_SECTORS.length;
        const arc = (Math.PI * 2) / numSectors;

        ctx.clearRect(0, 0, 560, 560);

        ctx.save();
        ctx.translate(cx, cy);
        ctx.rotate(angle);

        for (let i = 0; i < numSectors; i++) {
            const startAngle = i * arc;
            const endAngle = startAngle + arc;
            const sector = WHEEL_SECTORS[i];

            // 1. Сектор (клин)
            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.arc(0, 0, r, startAngle, endAngle);
            ctx.closePath();
            ctx.fillStyle = sector.color;
            ctx.fill();

            // Тонкая чистая разделительная линия
            ctx.lineWidth = 2.5;
            ctx.strokeStyle = 'rgba(255, 255, 255, 0.35)';
            ctx.stroke();

            // 2. Иконка и текст шрифтом из интерфейса
            ctx.save();
            ctx.rotate(startAngle + arc / 2);
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';

            // Иконка
            const wIc = getWheelIcon(sector);
            if (wIc) {
                ctx.save(); ctx.translate(r - 54, 0); ctx.rotate(Math.PI / 2);
                ctx.drawImage(wIc, -34, -34, 68, 68);
                ctx.restore();
            } else {
                ctx.font = '36px Arial';
                ctx.fillText(sector.icon, r - 48, 0);
            }

            // Текст награды (фиксированная сумма монет или бонус)
            let text = sector.label;
            if (sector.type === 'gold') {
                const amount = getWheelCoinReward(sector.ratio);
                text = amount < 10000 ? `+${amount.toLocaleString('ru-RU')}` : `+${formatNumber(amount)}`;
            }

            // Чистый и четкий шрифт точно как в карточках улучшений (Segoe UI / -apple-system, 800)
            ctx.font = '800 24px -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif';
            ctx.shadowColor = 'rgba(0, 0, 0, 0.75)';
            ctx.shadowBlur = 6;
            ctx.shadowOffsetX = 0;
            ctx.shadowOffsetY = 2;
            ctx.fillStyle = '#ffffff';
            // На секторе уже нарисована иконка — убираем эмодзи из подписи, чтобы не повторялись
            const label = String(window.I18N ? window.I18N.t(text) : text).replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}]/gu, '').replace(/\s+/g, ' ').trim();
            ctx.fillText(label, r - 128, 0);

            ctx.restore();
        }

        // Внешние золотые пины (гвоздики по ободу)
        for (let i = 0; i < numSectors; i++) {
            const pinAngle = i * arc;
            const px = Math.cos(pinAngle) * (r - 8);
            const py = Math.sin(pinAngle) * (r - 8);
            ctx.beginPath();
            ctx.arc(px, py, 6, 0, Math.PI * 2);
            ctx.fillStyle = '#ffffff';
            ctx.shadowColor = 'gold';
            ctx.shadowBlur = 6;
            ctx.fill();
            ctx.lineWidth = 2;
            ctx.strokeStyle = '#ffd700';
            ctx.stroke();
        }

        ctx.restore();
    }

    function isFreeSpinAvailable() {
        const featherLvl = (GameState.artifacts && GameState.artifacts.phoenix_feather) || 0;
        let cooldown = Math.max(10, 25 - (featherLvl * 3)) * 60 * 1000; // 25 минут база (или 22, 19, 16 с пером)
        const pet = getActivePet();
        if (pet && pet.id === 'unicorn') cooldown *= 0.7; // Единорог: −30%
        return (Date.now() - GameState.lastFreeSpinTime) >= cooldown;
    }

    function updateWheelUI() {
        const canFree = isFreeSpinAvailable();
        if (dom.wheelDot) {
            dom.wheelDot.classList.toggle('hidden', !canFree);
        }

        if (canFree) {
            if (dom.btnSpinWheel) dom.btnSpinWheel.classList.toggle('hidden', false);
            if (dom.btnSpinAd) dom.btnSpinAd.classList.toggle('hidden', true);
            setText(dom.wheelTimerText, '✨ Доступно бесплатное вращение!');
        } else {
            if (dom.btnSpinWheel) dom.btnSpinWheel.classList.toggle('hidden', true);
            if (dom.btnSpinAd) dom.btnSpinAd.classList.toggle('hidden', false);
            const featherLvl = (GameState.artifacts && GameState.artifacts.phoenix_feather) || 0;
            const cooldown = Math.max(10, 25 - (featherLvl * 3)) * 60 * 1000;
            const remaining = Math.max(0, cooldown - (Date.now() - GameState.lastFreeSpinTime));
            const totalSec = Math.ceil(remaining / 1000);
            const m = Math.floor(totalSec / 60);
            const s = totalSec % 60;
            const sFormatted = s < 10 ? '0' + s : s;
            setText(dom.wheelTimerText, `Бесплатно через: ${m}:${sFormatted}`);
        }
    }

    function spinWheel(isAd) {
        if (isWheelSpinning) return;
        initAudio();
        isWheelSpinning = true;

        if (dom.btnSpinWheel) dom.btnSpinWheel.disabled = true;
        if (dom.btnSpinAd) dom.btnSpinAd.disabled = true;
        if (dom.wheelResult) dom.wheelResult.textContent = 'Колесо вращается...';

        // Выбор сектора
        const numSectors = WHEEL_SECTORS.length;
        const targetSectorIndex = Math.floor(Math.random() * numSectors);
        const sectorArc = (Math.PI * 2) / numSectors;

        // Стрелка находится наверху (угол -Math.PI / 2)
        const baseTarget = (-Math.PI / 2) - (targetSectorIndex * sectorArc + sectorArc / 2);
        // 5-7 полных оборотов
        const fullSpins = (5 + Math.floor(Math.random() * 3)) * (Math.PI * 2);
        const startAngle = wheelAngle;
        const targetAngle = wheelAngle + fullSpins + ((baseTarget - (wheelAngle % (Math.PI * 2)) + Math.PI * 4) % (Math.PI * 2));

        const spinDuration = 4500;
        const startTime = performance.now();

        function animateSpin(now) {
            const elapsed = now - startTime;
            const progress = Math.min(1, elapsed / spinDuration);
            // Плавное торможение (cubic ease-out)
            const ease = 1 - Math.pow(1 - progress, 3.2);

            wheelAngle = startAngle + (targetAngle - startAngle) * ease;
            drawWheel(wheelAngle);

            // Звук трещотки
            const currentSector = Math.floor(((wheelAngle % (Math.PI * 2)) + Math.PI * 2) / sectorArc) % numSectors;
            if (currentSector !== lastPinSector) {
                lastPinSector = currentSector;
                playSound('tick');
            }

            if (progress < 1) {
                requestAnimationFrame(animateSpin);
            } else {
                isWheelSpinning = false;
                if (!isAd) {
                    GameState.lastFreeSpinTime = Date.now();
                }
                grantWheelReward(targetSectorIndex);
                if (dom.btnSpinWheel) dom.btnSpinWheel.disabled = false;
                if (dom.btnSpinAd) dom.btnSpinAd.disabled = false;
                updateWheelUI();
                saveGame();
            }
        }

        requestAnimationFrame(animateSpin);
    }

    function grantWheelReward(idx) {
        const sector = WHEEL_SECTORS[idx];
        playSound('bonus');
        spawnConfetti(window.innerWidth / 2, window.innerHeight / 2);
        trackQuestProgress('wheelSpins', 1);

        let rewardText = '';

        if (sector.type === 'gold') {
            const reward = getWheelCoinReward(sector.ratio);
            GameState.score += reward;
            GameState.totalEarned += reward;
            GameState.runCoinsEarned = (GameState.runCoinsEarned || 0) + reward;
            rewardText = `Вы выиграли +${reward < 10000 ? reward.toLocaleString('ru-RU') : formatNumber(reward)} монет! (${sector.name})`;
        } else if (sector.type === 'gems') {
            GameState.prestigeGems += sector.amount;
            rewardText = `Вы получили +${sector.amount} 💎 Кристалла Престижа!`;
        } else if (sector.type === 'megaboost') {
            const mult = (GameState.artifacts && GameState.artifacts.time_lord) ? 2 : 1;
            const duration = sector.duration * mult;
            GameState.megaBoostActiveUntil = Math.max(Date.now(), GameState.megaBoostActiveUntil || 0) + (duration * 1000);
            rewardText = `⚡ МЕГА-РЕЖИМ x5 АКТИВИРОВАН НА ${Math.round(duration / 60)} МИНУТ!`;
        } else if (sector.type === 'fever') {
            activateFever(sector.duration || 25, true);
            rewardText = `🔥 ОГОНЬ x3 на ${Math.round(feverDuration)} секунд!`;
        }

        if (dom.wheelResult) {
            dom.wheelResult.textContent = `🎉 ${sector.icon} ${rewardText}`;
        }
        showToast(`🎡 Рулетка: ${rewardText}`);
        updateUI();
    }

    // --- ОБНОВЛЕНИЕ СТАТИСТИКИ ИМПЕРИИ ---
    function updateStatsView(force) {
        if (!dom.statTotalCoins) return;
        // Окно статистики закрыто — не пересчитываем (раньше писали 11 чисел 10 раз в секунду)
        const statsModal = document.getElementById('modal-stats');
        if (!force && statsModal && statsModal.classList.contains('hidden')) return;

        let totalUpgrades = 0;
        for (const k in GameState.clickUpgrades) totalUpgrades += GameState.clickUpgrades[k];
        for (const k in GameState.autoUpgrades) totalUpgrades += GameState.autoUpgrades[k];

        const totalSeconds = Math.floor(GameState.timePlayedSeconds);
        const totalMinutes = Math.floor(totalSeconds / 60);
        let timeStr = `${totalSeconds} сек`;
        if (totalMinutes > 0) {
            const remSec = totalSeconds % 60;
            if (totalMinutes < 60) {
                timeStr = `${totalMinutes} мин ${remSec} сек`;
            } else {
                timeStr = `${Math.floor(totalMinutes / 60)} ч ${totalMinutes % 60} мин`;
            }
        }

        dom.statTotalCoins.textContent = formatNumber(GameState.totalEarned);
        dom.statTotalClicks.textContent = GameState.totalClicks.toLocaleString();
        dom.statTotalCrits.textContent = GameState.totalCrits.toLocaleString();
        dom.statTotalGifts.textContent = GameState.totalGiftsCaught.toLocaleString();
        dom.statTotalPrestiges.textContent = GameState.totalPrestiges.toLocaleString();
        if (dom.statUnlockedSkins) {
            dom.statUnlockedSkins.textContent = `${GameState.unlockedSkins ? GameState.unlockedSkins.length : 1} / ${SKINS_CONFIG.length}`;
        }
        dom.statTotalUpgrades.textContent = totalUpgrades.toLocaleString();
        dom.statTimePlayed.textContent = timeStr;
        dom.statCurrentClick.textContent = `+${formatRate(getClickPower())}`;
        dom.statCurrentPassive.textContent = `+${formatRate(getPassiveIncome())} / с`;
        dom.statTotalMultiplier.textContent = `x${getGlobalMultiplier().toFixed(1)}`;
    }

    // --- ОБНОВЛЕНИЕ ИНТЕРФЕЙСА (UI) ---
    let lastBuffsHtml = null;
    let lastGloryText = '';

    // Слава Империи: показываем бонус за достижения во вкладке «Достижения» и в статистике
    function updateGloryUI() {
        achCountCache.t = 0;
        const count = getUnlockedAchievementsCount();
        const pct = (getMilkMultiplier() - 1) * 100;
        // Из чего складывается Слава: база за достижение и все усилители
        const parts = [];
        const harmony = hasHeavenlyUpgrade('divine_harmony');
        parts.push(`${harmony ? '2' : '1'}% × ${count}${harmony ? ' (Небесная Гармония)' : ''}`);
        const pet = getActivePet();
        if (pet && pet.id === 'cat' && getPetLevel('cat') > 0) parts.push(`Кот-Банкир +${+(0.5 * getPetLevel('cat')).toFixed(1)}% за каждое`);
        const angels = getHeavenlyUpgradeLevel('kitten_angels');
        if (angels > 0) parts.push(`Небесные Котята ×${(1 + angels * 0.2).toFixed(1)}`);
        if (getTempleGloryMult() > 1) parts.push(`Хранитель Славы ×${getTempleGloryMult().toFixed(2)}`);
        const breakdown = parts.join(' · ');
        const pctText = pct >= 100 ? Math.round(pct) : Math.round(pct * 10) / 10;
        const text = `${count}|${pctText}|${breakdown}`;
        if (text === lastGloryText) return;
        lastGloryText = text;
        const banner = document.getElementById('glory-banner');
        if (banner) {
            banner.innerHTML = `<div class="glory-main">🏆 Слава Империи: <b>+${pctText}%</b> ко всему доходу</div>
                <div class="glory-sub">Каждое открытое достижение навсегда увеличивает доход. Открыто: ${count} из ${ACHIEVEMENTS_CONFIG.length}.</div>
                <div class="glory-sub glory-calc">${breakdown}</div>`;
        }
        const stat = document.getElementById('stat-glory');
        if (stat) stat.textContent = `+${pctText}%`;
    }

