        money_changer: 'old', print_house: 'old', pawn_shop: 'old', city_hall: 'old',
        jewelry_house: 'biz', royal_mint: 'biz', trade_port: 'biz', gold_mine: 'tech', singularity_reactor: 'tech',
        launch_pad: 'space', asteroid_mine: 'space', starship_yard: 'space', space_elevator: 'space', warp_gate: 'space',
        orbital_satellite: 'space', moon_base: 'space', mars_colony: 'space', solar_sail: 'space', dyson_sphere: 'space',
