                    if (rr > 0.7) o += `<rect x="${x + 2}" y="${top + 10}" width="${Math.min(12, bw - 4)}" height="6" rx="1" fill="${S.alt}" opacity=".35" class="c-neon"/>`;
                    if (rr < 0.35) o += `<path d="M${x + bw - 4} ${top - 12} L${x + bw - 4} ${top}" stroke="${S.edge}" stroke-width="0.7"/><circle cx="${x + bw - 4}" cy="${top - 12}" r="0.9" fill="${S.alt}" class="c-blink"/>`;
