        citySig = sig;
        cityNight = night;
        const builtCount = tiers.filter(t => t > 0).length;
        if (!builtCount) { layer.innerHTML = ''; layer.__view = ''; cityPrevNext = -1; cityPrevBuilt = 0; return; }
