            <linearGradient id="cbF" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#3b4aa6"/><stop offset=".55" stop-color="#252d75"/><stop offset="1" stop-color="#161b4d"/></linearGradient>
