    let lastEventTime = Date.now();
    let currentEvent = null;
    let eventDismissTimeout = null;

    // Переменные состояния текущей мини-игры
    let mgActive = false;
    let mgTimerInterval = null;
    let mgTimeLeft = 12;
    let mgScore = 0;
    let mgRafId = null;

    function checkRandomEvents(now) {
        if (currentEvent || mgActive || isRainActive) return;
        if (!isFeatureUnlocked('events')) {
            lastEventTime = Date.now();
            return;
        }

        // Частота событий: базовая 8–12 минут, уменьшается за каждый ур. Клевера
        const cloverLvl = (GameState.artifacts && GameState.artifacts.clover_abundance) || 0;
        const cooldownMult = 1 / (1 + cloverLvl * 0.25);
        const eventInterval = (480 + Math.random() * 240) * 1000 * cooldownMult * (isWeekend() ? 0.65 : 1); // 8–12 минут (в выходные чаще)

        if (Date.now() - lastEventTime >= eventInterval) {
            triggerRandomEvent();
        }
    }

    // Сезонные события: во время сезона иногда вместо обычного события идёт тематический «дождь»
    const SEASON_EVENTS = {
        halloween: { name: 'Тыквенная ночь', icon: '🎃', drops: ['🎃', '👻', '🍬'], text: 'Ловите тыквы и конфеты — среди них прячутся сезонные находки!' },
        newyear: { name: 'Снегопад подарков', icon: '🎁', drops: ['🎁', '❄️', '🍊'], text: 'С неба падают подарки и мандарины — ловите!' },
        valentine: { name: 'Дождь из сердец', icon: '💘', drops: ['💝', '🌹', '💌'], text: 'Ловите сердечки — в одном из них может быть находка!' },
        spring: { name: 'Охота за яйцами', icon: '🥚', drops: ['🥚', '🐣', '🌷'], text: 'Расписные яйца сыплются с неба — ловите!' },
        summer: { name: 'Звездопад над морем', icon: '🐚', drops: ['🐚', '🍉', '🍦'], text: 'Летний звездопад: ракушки, арбузы и мороженое!' }
    };
    const SEASON_EVENT_CHANCE = 0.35;

    function triggerRandomEvent() {
        lastEventTime = Date.now();
        // Указы: продолжение истории — в первую очередь, иначе с шансом 30%
        if (isFeatureUnlocked('decrees') && (hasDueDecreeChain() || Math.random() < 0.3)) {
            if (offerDecree()) return;
        }
        // Тема недели: её боссы и мини-игры приходят заметно чаще
        if (Math.random() < 0.3) { const tev = themeWeekEvent(); if (tev) { showEventInvite(tev); return; } }
        // Золотой дракон — редкий гость
        if (isFeatureUnlocked('dragon') && Math.random() < 0.18) {
            // боссы по очереди: какие открыты — из тех случайный
            const bosses = [DRAGON_EVENT];
            if (isFeatureUnlocked('kraken')) bosses.push(KRAKEN_EVENT);
            if (isFeatureUnlocked('golem')) bosses.push(GOLEM_EVENT);
            NEW_BOSS_EVENTS.forEach(b => { if (isFeatureUnlocked(b.id)) bosses.push(b); });
            // босс недели прилетает вдвое чаще
            const wb = weekBossId(); if (wb && bossEventById(wb)) bosses.push(bossEventById(wb));
            showEventInvite(bosses[Math.floor(Math.random() * bosses.length)]);
            return;
        }
        const season = getActiveSeason();
        if (season && SEASON_EVENTS[season.id] && Math.random() < SEASON_EVENT_CHANCE) {
            const se = SEASON_EVENTS[season.id];
            startGoldRain(16, { id: season.id, name: se.name, icon: se.icon, drops: se.drops, text: se.text });
            return;
        }
        const randIdx = Math.floor(Math.random() * RANDOM_EVENTS.length);
        const eventData = RANDOM_EVENTS[randIdx];

        if (eventData.type === 'rain') {
            startGoldRain(18);
        } else if (eventData.type === 'anomaly') {
            triggerCosmicAnomaly();
        } else {
            // Торговец и мини-игры не открываются сами — приходит приглашение, игрок решает
            showEventInvite(eventData);
        }
    }

    // ========================================================
    // УКАЗЫ ИМПЕРАТОРА — события с выбором (как карточки в Reigns)
    // Советник приносит ситуацию, игрок выбирает из двух вариантов.
    // tone: +1 — мягкое решение, −1 — строгое (влияет на «нрав правителя»), 0 — нейтральное.
    // risky: рискованный указ (на Тёмном пути приходят чаще и выигрыш больше, на Светлом — реже).
    // next: продолжение истории, которое придёт позже.
    // ========================================================
    const DECREE_INVITE_SECONDS = 30;
    function lvlOf(id) { return GameState.autoUpgrades[id] || 0; }
    // Монеты «за N минут дохода» (на старте — хотя бы немного)
    function incomeMinutes(min) { return Math.max(getPassiveIncome(true) * 60 * min, getClickPower(true) * 30 * min, 100 * min); }
    function bname(id) { const c = AUTO_UPGRADES_CONFIG.find(x => x.id === id); return c ? c.name : id; }
    function gainCoins(v) {
        v = Math.max(0, Math.floor(v));
        GameState.score += v; GameState.totalEarned += v; GameState.runCoinsEarned = (GameState.runCoinsEarned || 0) + v;
        return v;
    }
    function payCoins(v) { v = Math.min(GameState.score, Math.floor(v)); GameState.score -= v; return v; }
    // Временные эффекты указов: { k: 'income'|'tap'|'comet'|'cost'|'bld', id, m, from, until, label }
    function addDecreeBuff(k, m, minutes, label, id, delayMin) {
        if (!Array.isArray(GameState.decreeBuffs)) GameState.decreeBuffs = [];
        const from = Date.now() + (delayMin || 0) * 60000;
        GameState.decreeBuffs.push({ k, id: id || null, m, from, until: from + minutes * 60000, label });
    }
    function decreeMult(k, id) {
        const list = GameState.decreeBuffs;
        if (!Array.isArray(list) || !list.length) return 1;
        const now = Date.now();
        let m = 1;
        for (const b of list) {
            if (b.k !== k || now < b.from || now >= b.until) continue;
            if (k === 'bld' && b.id !== id) continue;
            m *= b.m;
        }
        return m;
    }
    function cleanDecreeBuffs() {
        if (!Array.isArray(GameState.decreeBuffs)) return;
        const now = Date.now();
        GameState.decreeBuffs = GameState.decreeBuffs.filter(b => b.until > now);
    }
    function pactRiskMult() { return GameState.pact === 'dark' ? 1.5 : 1; }   // выигрыш в рискованных указах
    function pactLossMult() { return GameState.pact === 'light' ? 0.5 : 1; }  // потери в рискованных указах

