            { label: 'Пусть терпят', tone: -1, desc: () => `+5 мин дохода · серверы ×0.7 на 30 мин`, apply: () => { gainCoins(incomeMinutes(5)); addDecreeBuff('bld', 0.7, 30, '🗄️ Горячие серверы ×0.7', 'server_rack'); } }
