            <div class="ps-list">${PASS_FREE.map((r, i) => `<div class="ps-row ${premCol ? '' : 'solo'} ${i < lvl ? 'open' : ''} ${i === lvl ? 'cur' : ''}"><span class="ps-num">${i + 1}</span>${cell(r, i, false)}${premCol ? cell(PASS_PREM[i], i, true) : ''}</div>`).join('')}</div>
